window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["04"]={"https://www.gov.uk/foreign-travel-advice/argentina":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"34a833433bcc6051bd79b0dc0fd99819483756ca0893f10a29b97d422b68ddfe","read":"https://www.gov.uk/api/content/foreign-travel-advice/argentina","bytes":81129,"x":"fulltext v1","title":"Argentina travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2026-05-07T17:26:11+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/argentina/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Argentina’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Argentina set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Argentine Consulate in the UK","https://clond.cancilleria.gob.ar/en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Argentina, your passport must be valid for the proposed duration of your stay. If you are a resident in Argentina, your passport must be valid for entry."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Argentina without a visa for tourism for up to 90 days."]},{"k":"p","s":["To stay longer, or to work or study, you must meet the Argentine government’s entry requirements. Contact the ",["Argentine Consulate in the UK","https://clond.cancilleria.gob.ar/en"],"."]},{"k":"p","s":["Immigration authorities no longer stamp passports on entry. If you need proof of your entry or exit, contact the ",["Argentine Migration Office","https://www.migraciones.gov.ar/transitos/"]," (in Spanish)."]},{"k":"p","s":["If you wish to extend your stay for another 90-day period, get advice from the Argentine Migration Office before your current stay ends."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["If you’re travelling to Argentina for any purpose other than tourism, contact the ",["Argentine Consulate in the UK","https://clond.cancilleria.gob.ar/en"]," about the visas or permits you need and how to apply."]},{"k":"h","s":["Travelling with children"]},{"k":"p","s":["Children aged 17 and under who are resident in Argentina need written permission (‘Autorización de viaje’) from the non-accompanying parents to leave the country."]},{"k":"p","s":["Non-resident children aged 17 and under who have remained in Argentina for 1 year or more are treated in line with resident children and also need permission. You can get permission from a notary public in Argentina or the ",["Argentine Migration Office","https://www.argentina.gob.ar/interior/migraciones/autorizacion-de-salida-del-pais-de-ninos-ninas-y-adolescentes"]," (in Spanish)."]},{"k":"p","s":["You can get full information on the requirements from the ",["Argentine Migration Office","https://www.argentina.gob.ar/justicia/derechofacil/leysimple/salida-de-menores-al-extranjero"]," (in Spanish) or from your nearest ",["Argentine consulate","https://cancilleria.gob.ar/en/representaciones"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Argentina guide","https://travelhealthpro.org.uk/country/11/argentina#Vaccine_Recommendations"],"."]},{"k":"p","s":["You may need a yellow fever certificate for onward travel to some other countries, due to the risk of yellow fever in Argentina."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Argentina","https://www.argentina.gob.ar/senasa/informacion-al-viajero/ingresar-o-regresar-al-pais"]," (in Spanish). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Argentina"]},{"k":"p","s":["You must ",["declare cash or travellers cheques worth more than 10,000 US dollars","https://www.afip.gob.ar/viajeros/ayuda/ingreso-egreso-de-valores.asp"]," (in Spanish)."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Argentina"]},{"k":"p","s":["Terrorist attacks in Argentina cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"hs","s":["Political protests"]},{"k":"p","s":["Political demonstrations and picketing are more common in Argentina than in the UK. Some demonstrations attract large numbers of people, and they can occasionally turn violent. Demonstrations are particularly common near Congress (‘Congreso’) and the Presidential Palace (‘Casa Rosada’)."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid all protests, demonstrations and marches"]},{"k":"li","s":["exercise normal caution at any large gathering"]},{"k":"li","s":["be aware of your surroundings"]},{"k":"li","s":["monitor the local news"]},{"k":"li","s":["follow the advice of local authorities"]},{"k":"p","s":["There have also been occasional Falklands-related protests, including outside the British Embassy and British-affiliated businesses in Argentina."]},{"k":"hs","s":["Demonstrations"]},{"k":"p","s":["Groups of demonstrators (‘piqueteros’) sometimes block major roads at times of social unrest. These can include the major routes into and out of Buenos Aires City. This can cause significant delays."]},{"k":"p","s":["When planning to travel:"]},{"k":"li","s":["monitor the local news"]},{"k":"li","s":["do not attempt to cross blockades"]},{"k":"li","s":["follow the advice of local authorities"]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Thieves and pickpockets operate on public transport and at bus and train terminals."]},{"k":"p","s":["To reduce the risk of theft:"]},{"k":"li","s":["always keep a close eye on your personal possessions – do not hang bags on the back of seats"]},{"k":"li","s":["carry cash out of sight or close to you – a money belt under your clothes is the safest option"]},{"k":"li","s":["you may need to produce your passport when paying with a credit card, but keep a copy somewhere safe"]},{"k":"li","s":["keep your bags close while you are checking into a hotel or hostel – thieves posing as hotel guests can snatch them"]},{"k":"p","s":["Thefts from unattended vehicles, especially hire cars, are also common. This happens frequently in Bariloche, but can happen across the country."]},{"k":"hs","s":["Street crime and scams"]},{"k":"p","s":["In crowded places, thieves can cut handbags open. They can snatch a mobile phone while you are using it on the street. Thieves on motorbikes can snatch bags from pedestrians."]},{"k":"p","s":["Thieves – often women – use distraction techniques and may work in teams of 2 or more. A common form of distraction theft reported in Buenos Aires is the ‘mustard scam’. Thieves take your bags while an accomplice pretends to help you remove mustard they have sprayed on you. If this happens to you, politely but firmly refuse help and walk away."]},{"k":"p","s":["In Buenos Aires, be particularly cautious in:"]},{"k":"li","s":["Palermo"]},{"k":"li","s":["San Telmo Market and general area of San Telmo"]},{"k":"li","s":["La Boca"]},{"k":"li","s":["The Ecological Reserve"]},{"k":"li","s":["Retiro"]},{"k":"li","s":["Florida Street"]},{"k":"li","s":["9 de Julio"]},{"k":"li","s":["Avenida de Mayo"]},{"k":"li","s":["Avenida Rivadavia near the obelisk"]},{"k":"li","s":["Retiro Bus terminal"]},{"k":"li","s":["Cruise and ferry terminals"]},{"k":"p","s":["In Mendoza, be particularly cautious downtown."]},{"k":"p","s":["In Santa Fe, be particularly cautious in Rosario."]},{"k":"hs","s":["Violent crime"]},{"k":"p","s":["Armed robberies are a risk. If you are the victim of a robbery, hand over your cash and valuables without resistance."]},{"k":"p","s":["Be vigilant in La Boca, Buenos Aires, especially in the streets outside the Caminito tourist area. To reduce your risk, stay in the designated tourist area where there are high-visibility police patrols."]},{"k":"hs","s":["Criminal kidnapping"]},{"k":"p","s":["Kidnappings including ‘express kidnappings’ – short-term opportunistic abductions – occasionally happen in Argentina. Victims of express kidnap are held and forced to empty their bank accounts by making bank transfers or going to ATMs, after which they are normally quickly released. Be aware of your surroundings and always let someone you trust know your whereabouts. If you are a victim of kidnapping, follow the kidnapper’s instructions."]},{"k":"p","s":["To reduce your risk:"]},{"k":"li","s":["avoid wearing expensive clothing or jewellery, particularly in public"]},{"k":"li","s":["avoid casual taxis – see ",["Transport risks","https://www.gov.uk/foreign-travel-advice/argentina/safety-and-security#transport-risks"]]},{"k":"li","s":["be vigilant, especially at night"]},{"k":"hs","s":["Drink and food spiking and scams"]},{"k":"p","s":["Drinks and food can be spiked and could put you at risk of robbery or assault. Do not leave drinks unattended in bars and restaurants and do not accept food or drink from strangers."]},{"k":"p","s":["Be alert to the possible use of ‘date rape’ and other drugs. Alcohol and drugs can reduce your vigilance, making you less in control."]},{"k":"p","s":["There have been reports of foreign tourists being robbed or assaulted after inviting into their accommodation someone they have recently met, online or in person."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Do not become involved with illegal drugs of any kind. Possession of even very small quantities can lead to a lengthy prison sentence."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Argentine society is open and diverse. Discrimination based on sexual orientation is rare. Same-sex marriage is legal. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Legal action against oil and gas companies"]},{"k":"p","s":["The government of Argentina has stated that it intends to pursue legal action against oil and gas companies engaged in hydrocarbon exploration in the Falkland Islands. If you’re travelling to Argentina and think you may be affected by this type of legal action, seek independent legal advice."]},{"k":"hs","s":["Surrogacy"]},{"k":"p","s":["Before you consider a surrogacy arrangement in Argentina, consider the challenges and risks involved, and make sure you seek specialist independent legal advice both in the UK and in Argentina. For more information, read FCDO guidance on ",["surrogacy overseas","https://www.gov.uk/government/publications/surrogacy-overseas"],"."]},{"k":"p","s":["Surrogacy is not regulated by law in Argentina and surrogacy arrangements are not enforceable in law."]},{"k":"p","s":["Local authorities may consider surrogacy arrangements to be illegal. Criminal investigations into surrogacy agencies and associated service providers are ongoing. Some intended parents have faced issues obtaining birth certificates and when attempting to leave Argentina with the child born to them through surrogacy."]},{"k":"p","s":["Children born through surrogacy in Argentina are Argentine citizens and must leave the country on an Argentine passport. They are also subject to local regulations applicable to the exit of minors in Argentina. See ",["Travelling with children","https://www.gov.uk/foreign-travel-advice/argentina/entry-requirements"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["If you take part in extreme or adventure sports, including paragliding, climbing, off-road driving and hot air ballooning, make sure:"]},{"k":"li","s":["adequate safety precautions are in place"]},{"k":"li","s":["you only use reputable operators and insist on training"]},{"k":"li","s":["your travel insurance covers all the activities you want to undertake and includes helicopter rescue and medical evacuation"]},{"k":"p","s":["You will have to pay for most helicopter rescues, including in Mount Aconcagua."]},{"k":"p","s":["Altitude sickness is a risk when hiking in parts of Argentina. See ",["Health","https://www.gov.uk/foreign-travel-advice/argentina/health"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Argentina, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You’ll need to have both the ",["1949 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["Respect for speed limits and traffic signals varies. Drivers can make unexpected turns or brake suddenly."]},{"k":"p","s":["Vehicle crime is a problem. Always keep car windows closed and doors locked when driving in major cities."]},{"k":"p","s":["Take care when driving in the province of Misiones, close to the borders with Paraguay and Brazil. The area is used to smuggle goods. Seek local advice from customs officials if you intend to drive in this area."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Book taxis in advance if possible. If you hail a taxi in the street, only use a ‘radio taxi’. These have a clearly visible logo on the car doors."]},{"k":"p","s":["The Buenos Aries government has a ",["list of authorised radio taxi operators","https://data.buenosaires.gob.ar/dataset/transportes-autorizados-pasajeros"]," (in Spanish)."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["Flights from Argentina can be unreliable. Check for delays or cancellations before travelling to the airport."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["Activist groups sometimes try to disrupt UK-flagged ships or commercial shipping working off the Falkland Islands. Contact the local authorities before travelling. Most cruise ships and visiting tourists should not be affected."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Many northern provinces experience occasional flooding. This can disrupt transport and could lead to shortages. Flash floods can occur during heavy rains, in provinces including Buenos Aires. Monitor local media and follow instructions given by the local authorities."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There is a risk of earthquakes in Argentina, particularly in the provinces of Mendoza, San Juan, Salta and Jujuy. Monitor media reports and follow the advice of local authorities."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Volcanic eruptions"]},{"k":"p","s":["The Copahue Volcano on the Argentina-Chile border erupts occasionally, and the authorities will evacuate the area. If you’re travelling to this area, monitor local media reports and follow the advice of the local authorities."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires can occur throughout Argentina and can spread rapidly. They may lead to road closures and affect the air quality in nearby areas."]},{"k":"p","s":["If you find yourself in or near the affected areas of any fire, monitor local media reports to stay informed of the rapidly evolving situation and follow the advice of the local authorities."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 107 or 911 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Argentina","https://travelhealthpro.org.uk/country/11/argentina#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Argentina","https://travelhealthpro.org.uk/country/11/argentina"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["dengue"]},{"k":"p","s":["Altitude sickness is a risk in parts of Argentina. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Hantavirus"]},{"k":"p","s":["Hantavirus is present in Argentina. Read more information about ",["hantavirus in Argentina on TravelHealthPro.","https://travelhealthpro.org.uk/updates.php?base=5054"]," Further guidance on hantavirus is available from the ",["UK Health Security Agency","https://ukhsa.blog.gov.uk/2026/05/05/what-is-hantavirus-how-is-it-transmitted-and-what-are-the-symptoms/"]," and ",["Argentina’s Ministry of Health","https://www.argentina.gob.ar/salud/glosario/hantavirus"]," (website in Spanish)."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Argentina"]},{"k":"p","s":["Medical facilities are good but can be expensive. Public hospitals tend to be crowded."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Argentina","https://www.gov.uk/government/publications/argentina-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Argentina"]},{"k":"p","s":["Ambulance: 107"]},{"k":"p","s":["Fire: 100"]},{"k":"p","s":["Police: 911 or 101"]},{"k":"p","s":["To contact the emergency line (911) in Buenos Aires from outside Argentina call: +54 11 4309 9600, extensions 261099 or 261098"]},{"k":"h","s":["Police assistance"]},{"k":"hs","s":["Buenos Aires"]},{"k":"p","s":["For English-language safety tips or to file a police report online, go to ",["the Buenos Aires Police website","https://turistas.seguridadciudad.gob.ar/"]," (only accessible in Argentina)."]},{"k":"p","s":["Tourist Police (‘Comisaría del Turista’): +54 911 5050 9260 (24 hours)"]},{"k":"p","s":["Tourist Police WhatsApp: +54 911 5050 9260"]},{"k":"hs","s":["Mendoza"]},{"k":"p","s":["Tourist Police (‘Comisaría del Turista’): +54 261 413 2135 (24 hours)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO provides guidance on how to help yourself stay safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Argentina"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Argentina"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Argentina"]," in Argentina"]},{"k":"li","s":["dealing with a ",["death in Argentina","https://www.gov.uk/government/publications/argentina-bereavement-information/argentina-bereavement-infotmation"]]},{"k":"li","s":["being ",["arrested in Argentina","https://www.gov.uk/government/publications/argentina-prisoner-pack/argentina-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/argentina/british-embassy-buenos-aires"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/argentina/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Argentina","https://www.gov.uk/government/publications/overseas-business-risk-argentina"]," on how to manage political, economic, and business security-related risks."]}],"chars":17370,"change":"New information about Hantavirus in Argentina (‘Health’ page)."},"https://theconversation.com/blue-wave-the-democrats-historic-midterm-election-gains-could-also-offer-canada-a-path-to-peace-295834":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"b178386655e03328f42ec1664fd151c9a7d8676098c6cfe155687781e80352b1","read":"https://theconversation.com/blue-wave-the-democrats-historic-midterm-election-gains-could-also-offer-canada-a-path-to-peace-295834","bytes":183957,"x":"fulltext v1","title":"Blue wave: The Democrats’ historic midterm election gains could also offer Canada a path to peace","by":[{"n":"Jason Opal","r":"Professor of History, The Ohio State University"}],"pub":"2026-11-04T16:30:24Z","mod":"","blocks":[{"k":"p","s":["During a ",["CBC Radio interview yesterday","https://www.cbc.ca/listen/live-radio/1-102-radio-noon-quebec/clip/16122602-trump-president-again.-what-thinking-about"],", I predicted a good night for the Democrats in the United States midterm elections — with the possibility of a great one."]},{"k":"p","s":["I was wrong."]},{"k":"p","s":["What happened was ",["the biggest rout of an incumbent party since 2006, when the Iraq War doomed George W. Bush’s Republican Party","https://www.npr.org/2026/11/04/nx-s1-6022532/how-this-years-midterms-stack-up-to-the-midterms-of-2006"],". It might turn out to be an even bigger win, especially in the semi-tropical conservative heartland known as the ",["Sun Belt","https://www.britannica.com/place/Sun-Belt"],", where the results seem like nothing less than a political revolution."]},{"k":"p","s":["For Canadians, this is likely good news — with Democrats now in control of both the House of Representatives and the Senate, the historical friendship between the U.S. and Canada may return to a firmer footing. In at least one Senate race — in Maine, where longtime Republican incumbent Susan Collins was defeated by Democrat Troy Jackson — ",["the Canada-U.S. trade war was a major campaign issue","https://www.cp24.com/news/money/2026/11/04/maine-elects-democratic-senator-after-race-that-featured-canada-us-trade-war/"],"."]},{"k":"p","s":["One former U.S. ambassador to Canada, Bruce Heyman, is already calling on Democrats to begin a reconciliation process with Canada."]},{"k":"h","s":["The landscape moves left"]},{"k":"p","s":["In terms of what happened stateside, let’s start with Ohio, where I’ve lived since moving here from Montréal shortly before the 2024 presidential election. Donald Trump won Ohio by 11 points that year. A hotly contested battleground in the early 2000s, the Buckeye State, ",["which has close economic ties with Canada","https://www.cbc.ca/news/world/in-ohio-canada-u-s-trade-war-sparks-anger-and-uncertainty-9.7324331"],", seemed safely Republican as recently as six months ago."]},{"k":"p","s":["But last night, all the usual Democratic voters, including younger people, professionals, racialized people and many low-wage workers, turned out in droves. Independents and moderates broke for the Democrats, and conservative voters showed far less enthusiasm for Republican candidates than they had for Trump."]},{"k":"p","s":["Take Lorain County, just west of Cleveland. A mostly white county of post-Second World War suburbs and poorer rural communities, ",["Lorain went for the Democratic candidate for Senate, Sherrod Brown, by 11 points","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-ohio-us-senate-special.html"],", just two years after favouring Trump by six."]},{"k":"p","s":["Lorain broke for Dr. Amy Acton, the Democratic candidate for governor, by 14 percentage points — an extra jab, perhaps, at her Republican opponent, Trump acolyte ",["Vivek Ramaswamy, who had run a brutal ad that questioned Acton’s honesty","https://www.cbc.ca/news/world/ohio-controversial-campaign-ad-ramaswamy-acton-9.7389687"]," regarding the sexual abuse she suffered as a child."]},{"k":"p","s":["In other traditional battlegrounds like Michigan and in newer “purple” states like North Carolina, the same story played out."]},{"k":"p","s":["Democrats and independents flooded the polls, while Republicans stayed home or strayed from the party standard. Virtually every county shifted left relative to 2024, often by double digits, enabling the Democrats to take firm control of the U.S. Congress while also delivering governorships and state legislatures long held by Republicans."]},{"k":"p","s":["The wide and deep character of the vote indicates a holistic rejection of Trump’s MAGA movement and his policies over the past two years, including the tariff war with Canada and other allies, the Iran war and the immigration crackdown. Voters also registered their disapproval of Republican efforts to redraw electoral districts and of ",["Trump’s “let it ride” approach to AI development","https://www.scientificamerican.com/article/trump-rejects-ai-regulation-citing-parallels-with-climate-change-in-un-address/"],"."]},{"k":"h","s":["The Sun Belt"]},{"k":"p","s":["But the bigger story happened farther south, in states like South Carolina, Mississippi, Louisiana and, above all, Texas."]},{"k":"p","s":["This huge band of rural poverty and suburban comfort — the Sun Belt — was once the place where cotton was king. It was a vast domain for a ",["virulent strain of slavery","https://www.hup.harvard.edu/books/9780674975385"]," that emerged in the early 1800s and refused to remain in the same country as Abraham Lincoln and his “ ",["Black Republicans","https://nkaa.uky.edu/nkaa/items/show/2044"],"” (the Republicans, founded in the mid-1850s, included abolitionists and pledged to contain slavery)."]},{"k":"p","s":["After the Civil Rights movement of the 1950s and ‘60s, these states shifted dramatically to the right, embracing the Republicans as the party of small government, evangelical piety and proud patriotism. Mostly white Republicans have simply overwhelmed the majority Black and Democratic strongholds of their states."]},{"k":"p","s":["In 2026, however, historically Black counties in places like the Mississippi Delta turned out in such huge numbers that the weakened Republican vote could no longer hold."]},{"k":"p","s":["As of this writing, the Democratic candidate for U.S. Senate, Scott Colom, is leading the incumbent Republican by ",["43 votes","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-mississippi-us-senate.html"]," out of nearly 950,000 cast."]},{"k":"p","s":["And then there is the biggest prize of all: Texas, one of only a handful of U.S. states that was once an independent republic, in this case a slaveholders’ cotton-growing frontier called the Lone Star Republic (1836-46)."]},{"k":"p","s":["Home to more than 31 million people, Texas is not shy about being Texas. (My grandfather, a Second World War veteran, proudly told me that he once got into a fist fight with his Texas-born superior when that officer tried to make my grandfather stand and sing, “The Yellow Rose of Texas.”)"]},{"k":"p","s":[["Around 40 per cent","https://www.texastribune.org/2023/06/21/census-texas-hispanic-population-demographics/"]," of Texans are Spanish-speaking voters who generally prefer Democrats but who had veered towards Trump two years ago."]},{"k":"p","s":["They veered back."]},{"k":"p","s":["For example, Webb County — on the border with Mexico — had gone to Trump in 2024 by two points. Last night, the Democratic candidate for U.S. Senate, James Talarico, won it by ",["47 points","https://www.nytimes.com/interactive/2026/11/03/us/elections/results-texas-us-senate.html"],"."]},{"k":"p","s":["I repeat: A county moved nearly 50 points in two years."]},{"k":"h","s":["What’s ahead?"]},{"k":"p","s":["What happens now depends on whether the Democrats can consolidate last night’s mighty alliance of moderates, young people, racialized people, professionals and lower wage earners."]},{"k":"p","s":["To do so, they will have to drop their occasional aversion to piety in public life (Talarico is a devout Presbyterian who gave his ",["victory speech","https://www.pbs.org/newshour/politics/watch-live-democrat-james-talarico-speaks-after-winning-texas-senate-seat"]," in front of the words “Love Thy Neighbor.”)"]},{"k":"p","s":["They will need to address economic problems. They will need to be disciplined."]},{"k":"p","s":["If they can do so, then the entire political map of the U.S. will be transformed, with the Sun Belt coloured purple and the Democratic Party capable of the kind of ",["sustained dominance we haven’t seen since Ronald Reagan’s Republicans in the 1980s","https://americanarchive.org/primary_source_sets/conservatism"],"."]},{"k":"p","s":["As Canadians have learned over the last two years, and more broadly over the last two centuries, America can always surprise you."]}],"chars":6002},"https://www.gov.uk/foreign-travel-advice/cote-d-ivoire":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"6afa81647505606b22ba8896b3457c2fea566507a44fc5de4ce13b47cd7c191b","read":"https://www.gov.uk/api/content/foreign-travel-advice/cote-d-ivoire","bytes":58822,"x":"fulltext v1","title":"Côte d'Ivoire travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-22T00:00:00+00:00","mod":"2026-11-09T16:16:31+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Borders with Burkina Faso and Mali"]},{"k":"p","s":["FCDO advises against all travel to:"]},{"k":"li","s":["within 40km of the borders with Burkina Faso and Mali"]},{"k":"li","s":["Northern Zanzan and Savanes provinces"]},{"k":"li","s":["Comoé National Park"]},{"k":"p","s":["This is due to an increased risk of terrorist attacks and kidnaps by terrorists based in the Sahel region, which includes Burkina Faso and Mali."]},{"k":"hs","s":["Côte d’Ivoire-Liberia border"]},{"k":"p","s":["FCDO advises against all but essential travel to within 20km of the border with Liberia owing to the risk of serious violence by local militias."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Côte d’Ivoire’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Côte d’Ivoire set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Embassy of Côte d’Ivoire in the UK","https://royaumeuni.diplomatie.gouv.ci/contacts.php?lang=en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Côte d’Ivoire, your passport must have an ‘expiry date’ at least 6 months after the date you arrive."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to enter Côte d’Ivoire."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":[["Apply and pay for an e-visa online","https://snedai.com/e-visa/"]," at least 10 working days before you travel to allow time for your application to be processed. Once it is approved, you will be able to collect your visa on arrival at Abidjan airport."]},{"k":"p","s":["If you are not an Economic Community of West African States (ECOWAS) national, you must hold a valid visa or have had your application for an e-visa approved before you travel."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Côte d’Ivoire, you must have a certificate to prove you’ve had a yellow fever vaccination."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Côte d’Ivoire guide","https://travelhealthpro.org.uk/country/112/cte-divoire-ivory-coast#Vaccine_Recommendations"],"."]},{"k":"h","s":["Ebola screening and health declaration"]},{"k":"p","s":["As a public health measure, Côte d’Ivoire has introduced screening for travellers arriving from countries affected by the Ebola outbreak. The World Health Organisation (WHO) has ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"]]},{"k":"p","s":["If you are travelling to or through Côte d’Ivoire from another African country, you must complete an online health declaration on the ",["Destination Côte d’Ivoire website","https://destinationci.com/"]," before you arrive. The QR code generated by the form must be shown on arrival."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Côte d’Ivoire","https://www.douanes.ci/particulier/voyageurs-nationaux-et-non-nationaux"]," (in French). You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking money into Côte d’Ivoire"]},{"k":"p","s":["You can take up to 500,000 West African CFA francs in cash into Côte d’Ivoire. You must declare any foreign currency."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Côte d’Ivoire","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Côte d’Ivoire"]},{"k":"p","s":["Terrorist attacks in Côte d’Ivoire cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals such as:"]},{"k":"li","s":["beach resorts"]},{"k":"li","s":["hotels"]},{"k":"li","s":["cafés and restaurants"]},{"k":"li","s":["major sporting events"]},{"k":"p","s":["The main threat in Côte d’Ivoire is from Jama’at Nusrat al-Islam wal-Muslimin (JNIM) and other al-Qa’ida (AQ) affiliated groups, including al-Qa’ida in the Islamic Maghreb (AQIM). JNIM is mainly active in the northern border areas, including the Comoé National Park in the north-east, but attacks could occur anywhere, including major towns and cities such as Abidjan."]},{"k":"p","s":["Stay aware of your surroundings, keep up to date with local media reports and follow the advice of the local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Political demonstrations sometimes take place in Abidjan and regional towns, particularly around elections. The authorities may use tear gas to disrupt unauthorised protests. Crowds can gather quickly, and roadblocks are common. It is possible that, in the event of significant unrest, internet access might be restricted."]},{"k":"p","s":["You should:"]},{"k":"li","s":["avoid crowds and demonstrations"]},{"k":"li","s":["follow local instructions and any additional security checks or measures"]},{"k":"li","s":["monitor local media"]},{"k":"p","s":["Be alert near military barracks and military installations."]},{"k":"h","s":["Personal security measures"]},{"k":"p","s":["If you’re staying for long in Côte d’Ivoire, you should seek professional security advice and regularly review personal security arrangements. You should keep a stock of food and water."]},{"k":"h","s":["Crime"]},{"k":"p","s":["There is a risk of violent crime in Abidjan, including armed break-ins to private residences and armed hold-ups in the street. Though not common, they do occur."]},{"k":"hs","s":["Street crime"]},{"k":"p","s":["To reduce your personal risk:"]},{"k":"li","s":["use taxi apps or pre-arranged private taxis"]},{"k":"li","s":["avoid using public transport after dark"]},{"k":"li","s":["make sure your accommodation has security measures in place"]},{"k":"li","s":["keep any valuables out of sight and do not wear expensive-looking jewellery or watches"]},{"k":"li","s":["do not walk after dark"]},{"k":"li","s":["take transport to use ATMs or to exchange money at the bank"]},{"k":"p","s":["To prevent card fraud, keep your bank card in sight when paying bills."]},{"k":"hs","s":["Vehicle crime"]},{"k":"p","s":["There have been attacks by armed robbers on private cars driving on the main roads in the west of the country. You could be at risk in daylight as well as at night."]},{"k":"p","s":["Keep your car doors locked, windows shut and all valuables out of sight while driving."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You must carry your passport. Carry the original as the police will not always accept copies."]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["Dress modestly when visiting religious places or buildings."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Drug trafficking and possession are illegal. If you’re found guilty, you could receive a long prison sentence or a heavy fine."]},{"k":"hs","s":["Using cameras in secure areas"]},{"k":"p","s":["It is prohibited to take photographs near sensitive installations, including:"]},{"k":"li","s":["military sites"]},{"k":"li","s":["government buildings"]},{"k":"li","s":["radio and TV stations"]},{"k":"li","s":["the Presidency building"]},{"k":"li","s":["Abidjan Airport"]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is not illegal in Côte d’Ivoire, but the law does not recognise same-sex partnerships or marriage. Attitudes are less tolerant and there is no specific anti-discrimination law to protect LGBT+ people."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Côte d’Ivoire, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You must have the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," or a local driving licence. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["In case the police stop you, always carry your UK licence and an IDP, or a local licence, plus your car registration documents and insurance card."]},{"k":"p","s":["If you want to apply for a local driving licence, get your UK driving licence ",["authenticated by the DVLA","https://www.gov.uk/view-driving-licence"]," in the UK."]},{"k":"hs","s":["Road conditions"]},{"k":"p","s":["Driving standards in Côte d’Ivoire are poor. There is a high number of fatal road accidents and emergency services outside of Abidjan are unreliable."]},{"k":"p","s":["Road conditions are improving in Abidjan, but driving outside the capital is much more difficult. Poorly lit roads and the risk of stray livestock make driving particularly dangerous at night. During the rainy season minor roads may become impassable."]},{"k":"hs","s":["Public transport"]},{"k":"p","s":["Take care when using public transport – driving standards and vehicle maintenance are poor."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Taxis, including share taxis, operate in Abidjan and other cities in Côte d’Ivoire. Vehicles used as taxis tend to be old and there may be issues with the standard of maintenance. Ride-hailing apps are also available, and vehicles operating on these apps tend to be better maintained. Although no taxi can be guaranteed safe, we recommend using ride-hailing apps where possible."]},{"k":"hs","s":["Roadblocks and checkpoints"]},{"k":"p","s":["There are roadblocks and checkpoints in and around Abidjan and across the country. The Côte d’Ivoire government is currently running a campaign against bad driving and unroadworthy vehicles."]},{"k":"p","s":["Slow down at any type of checkpoint and stay calm. Comply when the police ask you for routine paperwork such as photo ID, driving licence, insurance and vehicle registration or ownership documents, which you should carry with you in your vehicle."]},{"k":"p","s":["Beware of unofficial roadblocks – you could be robbed or assaulted. These are sometimes set up by armed bandits known as ‘coupeurs de route’ and are mostly on secondary or quiet roads."]},{"k":"p","s":["If the police issue you with a fine, they should also issue you with related paperwork."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["The rainy season is between May and November. Torrential rains often cause flooding, landslides and large potholes. Flash flooding has caused deaths. Monitor local weather reports."]},{"k":"hs","s":["Ocean currents"]},{"k":"p","s":["Ocean currents are very strong along the coast. Rip tides cause many swimming accidents and drownings each year. There is no lifeboat or rescue service."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Côte d’Ivoire. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire"],"."]},{"k":"h","s":["Borders with Burkina Faso and Mali"]},{"k":"p","s":["FCDO advises against all travel to within 40km of the borders with Burkina Faso and Mali. There is an increased risk of terrorist attacks and kidnaps by terrorists based in the Sahel region, which includes Burkina Faso and Mali."]},{"k":"h","s":["Northern provinces"]},{"k":"p","s":["FCDO also advises against all travel to:"]},{"k":"li","s":["Northern Zanzan and Savanes provinces"]},{"k":"li","s":["Comoé National Park"]},{"k":"p","s":["See ",["Safety and security","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/safety-and-security"]," for details about terrorism risks in Côte d’Ivoire."]},{"k":"h","s":["Côte d’Ivoire-Liberia border"]},{"k":"p","s":["FCDO advises against all but essential travel to within 20km of the border with Liberia. This is due to the risk of clashes between local militias and security forces. Fatal clashes have taken place in and around this area in the past. If you travel to this area, seek professional security advice locally."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 185 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Côte d’Ivoire","https://travelhealthpro.org.uk/country/112/cote-divoire-ivory-coast#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Côte d’Ivoire","https://travelhealthpro.org.uk/country/112/cote-divoire-ivory-coast"],", including:"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["malaria and dengue"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["Ebola virus"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Côte d’Ivoire"]},{"k":"p","s":["Medical facilities in Abidjan are of a reasonable standard but can be expensive. Emergency facilities are limited to a few major hospitals. Outside of Abidjan medical facilities are rudimentary."]},{"k":"p","s":["Serious medical treatment could require medical evacuation back to the UK. Make sure you have adequate travel health insurance and funds to cover the cost of any medical treatment and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Côte d’Ivoire","https://www.gov.uk/government/publications/cote-divoire-list-of-medical-facilitiespractitioners/cote-divoire-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Côte d’Ivoire"]},{"k":"p","s":["Ambulance: 185"]},{"k":"p","s":["Fire: 180"]},{"k":"p","s":["Police: 110, 111 or 170"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=C%C3%B4te%20d%27Ivoire"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=C%C3%B4te%20d%27Ivoire"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=C%C3%B4te%20d%27Ivoire"]," in Côte d’Ivoire"]},{"k":"li","s":["dealing with a ",["death in Côte d’Ivoire","https://www.gov.uk/government/publications/cote-divoire-bereavement-death-abroad"]]},{"k":"li","s":["Being ",["arrested or imprisoned in Côte d’Ivoire","https://www.gov.uk/government/publications/cote-divoire-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/cote-d-ivoire/british-embassy-abidjan"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/cote-d-ivoire/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Côte d’Ivoire","https://www.gov.uk/government/publications/overseas-business-risk-cote-divoire"]," on how to manage political, economic, and business security-related risks."]}],"chars":15030,"change":"New information about Ebola screening and health declarations when arriving in country (‘Entry requirements’ page)."},"https://theconversation.com/nvidia-jensen-huang-and-the-history-of-sexpionage-296187":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"aa49453161effce2d3bf03fe94f372a23ac46aa425c88c7c3f2a49ba3147f8b8","read":"https://theconversation.com/nvidia-jensen-huang-and-the-history-of-sexpionage-296187","bytes":183735,"x":"fulltext v1","title":"Nvidia, Jensen Huang and the history of ‘sexpionage’","by":[{"n":"Robert Dover","r":"Professor of Intelligence and National Security & Dean of Faculty, University of Hull"}],"pub":"2026-11-11T12:02:33Z","mod":"","blocks":[{"k":"p","s":["A large portion of intelligence work is focused on collecting information your competitor or adversary does not want you to have. But another key focus of intelligence is on compromising key individuals."]},{"k":"p","s":["This involves damaging reputations or putting people in a position where they might disclose sensitive information. To achieve that, ",["intelligence","https://theconversation.com/topics/spying-1616"]," agencies have often used the suggestion, promise or reality of sex."]},{"k":"p","s":["The reemergence of interest in ",["“sexpionage”","https://www.independent.co.uk/news/world/politics/how-russia-still-trying-to-use-sex-for-spying-a7529221.html"]," comes from recent ",["allegations","https://www.nytimes.com/2026/11/08/technology/nvidia-investigation-jensen-huang.html"]," around Nvidia CEO Jensen Huang and ",["his relationship with","https://www.ft.com/content/a55a2a22-4479-4f93-a445-6147a5c6d790?syn-25a6b1a6=1"]," an executive of a ",["partner company","https://www.nytimes.com/2025/10/09/technology/nvidia-chips-china-megaspeed.html"],". The US intelligence community ",["believes","https://www.nytimes.com/2026/11/09/business/jensen-huang-china-spying.html"]," the woman in question, Alice Huang, is connected to Chinese intelligence."]},{"k":"p","s":[["Nvidia","https://theconversation.com/why-is-nvidia-so-powerful-in-the-ai-world-and-what-could-jensen-huangs-scandal-really-cost-296257"],", the computing power behind American AI advances and a ",["significant financial factor","https://www.reuters.com/business/media-telecom/no-ordinary-ceo-why-ai-race-cannot-do-without-nvidias-jensen-huang-2026-11-09/"]," in US stock market gains, has launched its own investigation. And the US president, Donald Trump, has ",["said the FBI","https://www.bbc.co.uk/news/articles/cqg7x7dpvym8o"]," is looking into the situation. China has ",["dismissed the claims","https://www.nytimes.com/2026/11/09/business/jensen-huang-china-spying.html"]," as a groundless smear campaign."]},{"k":"p","s":["The situation has drawn attention to the wider vulnerabilities the west has to spying. The key question is: does any western organisation with deep exposure to Chinese partners have a realistic understanding of how information moves out of those relationships?"]},{"k":"p","s":["My assessment is they do not. In part, this is because Chinese intelligence is widely viewed as a mirror of the west’s heavily controlled intelligence agencies."]},{"k":"p","s":["But China’s 2017 ",["National Intelligence Law","https://www.chinalawtranslate.com/en/national-intelligence-law-of-the-p-r-c-2017/"]," requires organisations and citizens to support and cooperate with state intelligence work. Any partner with meaningful ties to China is thus a potential conduit, regardless of whether they have been formally recruited."]},{"k":"h","s":["‘Honeytrap’ agents"]},{"k":"p","s":["Sexpionage captures headlines and drags eyeballs. The promise of a fallen man (nearly always a man) has been a staple of tabloid newspapers, novels, films and television for well over a century. Among the most prominent examples is ",["the Profumo Scandal","https://www.tandfonline.com/doi/full/10.1080/13619462.2016.1261698"]," in the 1960s."]},{"k":"p","s":["At that time, the then-UK secretary for war, John Profumo, ",["had an affair","https://blogs.bodleian.ox.ac.uk/archivesandmanuscripts/2013/03/22/50-years-ago-the-profumo-affair/"]," with a 19-year-old woman, who was also intimate with a Soviet defence attache. This created an intelligence vulnerability. Similarly, ",["suggestions","https://theconversation.com/a-whiff-of-espionage-around-the-epstein-files-points-to-how-intelligence-and-influence-interact-275344"]," of government connections to the dead and disgraced financier Jeffrey Epstein provide whiffs of espionage to sexual abuse and compromise."]},{"k":"p","s":["Read more: ",["A whiff of espionage around the Epstein files points to how intelligence and influence interact","https://theconversation.com/a-whiff-of-espionage-around-the-epstein-files-points-to-how-intelligence-and-influence-interact-275344"]]},{"k":"p","s":["Sexpionage can even be seen in biblical accounts. The Book of Joshua tells the story of a woman called Rahab who ",["used her access","https://engelsbergideas.com/portraits/rahab-the-old-testaments-female-super-spy/"]," to Jericho’s military leaders to pass on secrets to the Israelites. It also featured in the intrigues of the middle ages and prominently in the first world war."]},{"k":"p","s":[["Mata Hari","https://www.theguardian.com/lifeandstyle/2016/dec/05/the-real-mata-hari-executed-abused-woman"],", a Dutch dancer and spy, was executed in 1917 having promised intelligence to both the French and German militaries. These intrigues were based on her entanglements with senior military officials on both sides."]},{"k":"p","s":["Later, during the cold war, the Soviets and East Germans refined their use of so-called “honeytrap” agents towards using ordinary looking, reasonably well-educated men and women with whom a relationship ",["would look believable","https://archive.org/details/spymastermythirt0000kalu"],". These relationships often began without coercion and consequently the betrayal of secrets was more enduring and deniable."]},{"k":"p","s":["A large number of western officials were recalled home from Moscow or Soviet satellite states during this period after being caught in compromising and staged situations with Russian agents. There were some, like ",["British civil servant John Vassall","https://www.politics.co.uk/history/admiralty-clerk-john-vassall-arrested-for-spying/"],", whose compromised status was not detected and who spied for the Soviet Union."]},{"k":"p","s":["Intelligence agencies also had conspicuous success during the cold war through the exploitation of closeted gay men like Vassall and the Canadian ambassador to Moscow, ",["John Watkins","https://www.upi.com/Archives/1982/01/06/John-Watkins-acted-like-a-man-with-little-time/4355379141200/"],", whose compromise might see them prosecuted if they did not comply."]},{"k":"p","s":["According to author Henry Schlesinger, the purpose of sexpionage falls ",["into four categories","https://uk.bookshop.org/p/books/honey-trapped-sex-betrayal-and-weaponized-love-henry-r-schlesinger/8a4ad38b044620b4"],". First is to control or coerce the target, persuading them to spy. Second is to collect “pillow talk”, the injudicious comments to a lover in an intimate moment and giving access to their phones or computers."]},{"k":"p","s":["The third category is collecting information that allows for further exploitation of the target. Minor legal snags such as recreational drug use or driving infringements can be leveraged further. And the fourth is collecting a means by which to discredit protest or political movements."]},{"k":"p","s":["This is essentially the subject of the current ",["Undercover Policing Inquiry","https://www.ucpi.org.uk/"]," in the UK. Evidence to the inquiry by the Metropolitan Police has confirmed that ",["undercover police officers","https://www.theguardian.com/uk/2013/mar/01/spy-mark-kennedy-number-relations"]," engaged in sexual relationships to collect intelligence and ",["undermine protest groups","https://www.theguardian.com/uk-news/2024/dec/08/undercover-officer-denies-role-in-arson-attack-on-debenhams-in-1987"]," from the 1970s until at least 2011."]},{"k":"h","s":["Targeting tech executives"]},{"k":"p","s":["If we bring sexpionage to the modern day, what might an intelligence agency or officer be considering when targeting a technology executive?"]},{"k":"p","s":["Receiving forewarning of US government decisions is a key interest for China, as is gauging the extent to which the US tech industry relies on Taiwan. Moreover, access to technology or finance executives and companies is valuable."]},{"k":"p","s":["We also need to consider the incentives of technology leaders. Private firms are not obliged to engage in ",["counterintelligence","https://www.fbi.gov/investigate/counterintelligence"],", the business of finding spies. Stopping a major commercial partnership because there is some evidence of exposure to a foreign government could also be seen as bad business."]},{"k":"p","s":["However, businesses should have some curiosity in who they are trading with, not least because of the ",["strong market responses","https://www.theguardian.com/business/live/2026/nov/09/nvidia-jensen-huang-scandal-investigation-ai-industry-tech-stocks-recovery-slump-latest-news-updates"]," to this. Nvidia’s share price ",["tumbled","https://www.nytimes.com/2026/11/09/business/nvidia-stock-price-jensen-huang-ceo.html"]," US$330 billion (£246 billion) after the company announced it would launch an investigation into the recent reports."]},{"k":"p","s":["Governments need to watch closely for compromise activities against companies they now think of as ",["core infrastructure","https://link.springer.com/article/10.1007/s41125-026-00120-z"],". In the Nvidia case, it has been ",["reported","https://www.nytimes.com/2026/11/08/us/politics/rubio-nvidia-ceo-chinese-spy.html"]," that US government officials suspected there was a problem before allowing the company’s ",["advanced H200 chips","https://en.sedaily.com/international/2026/11/08/nvidias-huang-faces-scrutiny-over-h200-china-sales-alleged"]," to be exported to China."]},{"k":"p","s":["This is the sort of vulnerability intelligence agencies are there to prevent."]}],"chars":6083},"https://www.gov.uk/foreign-travel-advice/czechia":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"66780923ccc64cb210ead3defc358a4c3ce627c34cab41cf3027922e1fa27026","read":"https://www.gov.uk/api/content/foreign-travel-advice/czechia","bytes":79556,"x":"fulltext v1","title":"Czechia travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2026-08-11T10:18:36+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/czech-republic/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Czechia set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Czech Embassy in the UK","https://www.mzv.cz/london"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Czechia follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the day you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can travel without a visa to the Schengen area, which includes Czechia, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The requirements for ",["working in Czechia","https://www.gov.uk/guidance/travel-to-the-czech-republic-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Czech border control, you may also need to:"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, you must meet the Czech government’s entry requirements. Check which type of visa or permit you need with the ",["Czech Embassy in the UK","https://mzv.gov.cz/london/en/visa_and_consular_information/visa_information/index.html"],"."]},{"k":"p","s":["If you stay in Czechia with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Czechia","https://www.gov.uk/guidance/living-in-the-czech-republic#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Border controls at Germany’s land borders"]},{"k":"p","s":["There are temporary border controls in place to travel into Germany. Check the ",["entry requirements for Germany","https://www.gov.uk/foreign-travel-advice/germany/entry-requirements"],"."]},{"k":"h","s":["Registering with the police"]},{"k":"p","s":["If you do not have a Czech residence permit, you must register your address with the ",["nearest foreign police department","https://www.policie.cz/clanek/oddeleni-pobytovych-agend.aspx"]," (in Czech) within 3 days of arriving. You can also register through your hotel or accommodation service. If you do not register, you could get a fine of up to 3,000 Czech koruna."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods that can be brought into and taken out of Czechia","https://www.celnisprava.cz/en/clo/informace-pro-fyzicke-osoby/Pages/information-of-the-customs-administration-of-the-czech-republic-for-travellers-regarding-modifications-as-regards-imports-o.aspx"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food into Czechia"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://food.ec.europa.eu/animals/animal-products-movements/personal-imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into or out of Czechia"]},{"k":"p","s":["Declare cash or travellers cheques if the value is 10,000 euros or more. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave. For more information, see ",["import and export of financial funds","https://www.celnisprava.cz/en/dalsi-kompetence/informace-pro-fyzicke-osoby/Pages/import-and-export-of-financial-funds.aspx"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Czechia"]},{"k":"p","s":["Terrorist attacks in Czechia cannot be ruled out."]},{"k":"p","s":["You should be aware of the global risk of indiscriminate terrorist attacks which could be in public places, including in places frequented by expatriates and foreign travellers."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Public protests may happen at short notice. These have been peaceful but take care in crowded places and follow the instructions of local authorities."]},{"k":"h","s":["Crime"]},{"k":"p","s":["If you are victim of crime, immediately call 112 for assistance."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Petty theft is a problem, especially in major tourist areas in Prague. There is a risk of pickpocketing:"]},{"k":"li","s":["on busy metro and bus routes from Prague airport to the city centre"]},{"k":"li","s":["on trams to popular tourist sites like Prague Castle"]},{"k":"li","s":["in busy tourist areas"]},{"k":"p","s":["Take care of yourself and your belongings in the same way as you would do in the UK. Avoid leaving your belongings unattended."]},{"k":"p","s":["Report thefts in person to the nearest Czech police station within 24 hours and get a police report crime number for insurance purposes."]},{"k":"p","s":["Prague police station (Jungmannovo namesti 9, Prague 1, nearest metro stop is Mustek) is open 24 hours a day and would provide English speaking interpreters."]},{"k":"p","s":["You can also get a police report from the police station at the airport. See ",["Prague police station contact details","https://www.policie.cz/SCRIPT/imapa.aspx?area=pha&docid=672&nid=269&num=1"]," (in Czech)."]},{"k":"p","s":["Every lamppost in Prague has a 6-digit number posted at eye level. These codes will help you tell the police where you are if you cannot give them an exact address."]},{"k":"hs","s":["Drink spiking"]},{"k":"p","s":["There is a risk of drink spiking in bars and clubs. Be careful not to take drinks from strangers or leave your drinks unattended."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Beware of criminals pretending to be plainclothes policemen who ask to see your foreign currency and passport. Czech police officers do not have the right to do this. Do not show them your money. Instead, offer to go with them to the nearest police station. You can also call 112 to check their identity."]},{"k":"h","s":["Travelling in groups"]},{"k":"p","s":["If you’re travelling in a group, keep a note of your hotel phone number and address in case you are separated. Leave contact details with a friend or relative in the UK."]},{"k":"h","s":["Prague safety issues"]},{"k":"p","s":["Prague city police advise visitors to:"]},{"k":"li","s":["always change money at a currency exchange or bank rather than on the street as this money is often counterfeit"]},{"k":"li","s":["take care when using cash machines"]},{"k":"li","s":["avoid contact with sex workers"]},{"k":"li","s":["be aware of consumption charges in night clubs as they are often high"]},{"k":"li","s":["be careful with consumption cards, which carry high financial penalties if you lose them before you pay your bill"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["It is a legal requirement to carry ID. Always carry your passport. The police may fine or arrest you if you do not. They will normally accept a scan of your passport if you have not committed a crime."]},{"k":"hs","s":["Drunken and offensive behaviour"]},{"k":"p","s":["Stag groups are not allowed to enter some city centre bars and restaurants. You may be arrested or fined for drunken or offensive behaviour. Police may take you to ‘sober-up’ facilities for a temporary period, and you will have to pay for your stay."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["The possession, sale and distribution of drugs, including cannabis, is illegal, and the drugs are often dangerous counterfeits. Some shops, particularly in Prague, advertise ‘cannabis products’, which contain trace amounts of THC permissible under Czech law."]},{"k":"p","s":["You should expect severe penalties such as a long jail sentence and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through the airport. Convictions carry sentences of up to 18 years."]},{"k":"p","s":["Airports in Czechia have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex relationships and civil partnerships are legal in Czechia, but same-sex marriages are not recognised in Czech law. Registered same-sex partnerships are awaiting presidential approval. Same-sex couples showing affection in public could receive unwanted attention. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Surrogacy"]},{"k":"p","s":["It is illegal to earn money from a surrogacy arrangement."]},{"k":"p","s":["The police may charge you if you are:"]},{"k":"li","s":["a surrogate mother"]},{"k":"li","s":["a British national who plans to take a child born through surrogacy"]},{"k":"li","s":["an agent organising the handover"]},{"k":"p","s":["FCDO advises against making surrogacy arrangements in Czechia or moving surrogacy arrangements from other countries."]},{"k":"p","s":["You should get specialist legal advice in the UK and Czechia. See ",["surrogacy arrangements in foreign countries","https://www.gov.uk/government/publications/surrogacy-overseas/surrogacy-overseas"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Czechia, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Czechia guide","https://www.rac.co.uk/drive/travel/country/czech-republic/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Czechia. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the correct version of the ",["international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If you are visiting Czechia, you may be able to use your ",["Blue Badge","https://www.gov.uk/government/publications/blue-badge-using-it-in-the-eu/using-a-blue-badge-in-the-european-union"]," in some circumstances. Check local parking rules."]},{"k":"p","s":["Drink-driving is a serious offence in Czechia. If you are tested and found to have any alcohol or drugs in your system, you may face a fine of up to 50,000 Czech koruna, confiscation of your licence and possible imprisonment. The Czech police can ask any driver to take a breathalyser test on the spot."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["It’s safer to use a major taxi company than to pick one up in the street. Some taxis charge high prices. Always check the rates on the side of the taxi before getting in."]},{"k":"p","s":["Beware of drivers pretending to be taxi services but offering rides in unmarked cars and overcharging for journeys. See information on ",["using Uber at Prague airport","https://www.prg.aero/en/taxi"],", including how to book through the app, at a self-service kiosk or at service counters. Booking through a kiosk is usually slightly more expensive."]},{"k":"hs","s":["Buses and trams"]},{"k":"p","s":["See ",["Prague public transport information and journey planner","https://www.dpp.cz/en"]," in English."]},{"k":"p","s":["Be careful near tram tracks and make sure you look both ways as trams cannot stop quickly. Trams have the right of way on zebra crossings."]},{"k":"p","s":["You may get a fine if you do not cross roads and tram tracks at pedestrian crossings. You can also get a fine if you cross when the pedestrian crossing light is not green."]},{"k":"p","s":["You must validate your ticket in a ticket machine before starting a journey on public transport. You do not need to validate tickets bought from self-service terminals on trams and buses. Officials patrol public transport and will issue an on-the-spot fine of 1,000 Czech koruna (around £35) if you do not hold a validated ticket. If fined, you should get a receipt. If you cannot pay immediately, the police can get involved and the fine could increase to 1,500 koruna."]},{"k":"p","s":["The 30 and 90-minute journey adult tickets for bus, tram and metro are not valid on the Petřín Hill funicular railway in Prague. You need a specific 60-koruna ticket from the vending machines at funicular railway stops, or a 24-hour ticket (or longer)."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/extreme-weather-and-natural-hazards"],"."]},{"k":"p","s":["You can access ",["local forecasts and weather warnings","https://www.chmi.cz/?l=en"]," for Czechia. Follow the instructions of local authorities."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Czechia","https://travelhealthpro.org.uk/country/62/czech-republic#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Czechia","https://travelhealthpro.org.uk/country/62/czech-republic#General_Information"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Czechia"]},{"k":"p","s":["FCDO has a ",["list of medical providers in Czechia","https://www.gov.uk/government/publications/czech-republic-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Czechia, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Czechia","https://www.gov.uk/guidance/living-in-the-czech-republic#healthcare-in-the-czech-republic"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Czechia"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Czech%20Republic"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Czech%20Republic"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Czech%20Republic"]," in Czechia"]},{"k":"li","s":["dealing with a ",["death in Czechia","https://www.gov.uk/government/publications/czech-republic-bereavement-packinformation"]]},{"k":"li","s":["being ",["arrested or imprisoned in Czechia","https://www.gov.uk/government/publications/czech-republic-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/czech-republic/british-embassy-prague"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/czech-republic/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Czechia","https://www.gov.uk/government/publications/overseas-business-risk-czech-republic"]," on how to manage political, economic, and business security-related risks."]}],"chars":18681,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."},"https://theconversation.com/the-milburn-report-sets-out-a-plan-to-improve-the-lives-of-young-people-who-are-neet-experts-respond-296758":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"500ad853b7b636a235b89485a9f77380454b476660b28d7e9798de2e88eee44c","read":"https://theconversation.com/the-milburn-report-sets-out-a-plan-to-improve-the-lives-of-young-people-who-are-neet-experts-respond-296758","bytes":189360,"x":"fulltext v1","title":"The Milburn report sets out a plan to improve the lives of young people who are Neet – experts respond","by":[{"n":"Lisa Russell","r":"Professor of Education and Employment, Manchester Metropolitan University"},{"n":"Fabian Stephany","r":"Departmental Research Lecturer and Economist in AI and Work, University of Oxford"},{"n":"Rachel Scarfe","r":"Lecturer in Economics, University of Stirling"},{"n":"Tony McNulty","r":"Lecturer/Teaching Fellow, British Politics and Public Policy, Queen Mary University of London"}],"pub":"2026-11-17T15:38:09Z","mod":"","blocks":[{"k":"p","s":["Former Labour minister Alan Milburn has finally delivered his long-awaited report on the UK’s nearly 1 million young people who are not in education, employment or training ( ",["Neet","https://theconversation.com/topics/neet-9185"],"). In it, he proposes guaranteed work or training opportunities for all 16 to 24-year-olds, but also outlines the need to shift the focus away from benefits. It will be up to the government to decide which ideas to take forward, but our panel of experts has assessed some of the key issues."]},{"k":"h","s":["Changed landscape for Labour on welfare reform"]},{"k":"p","s":["Everything about the ongoing debate by government around the issue of welfare reform is different this time. Former prime minister Keir Starmer’s attempts ",["to secure reform","https://www.theguardian.com/politics/2025/jul/01/welfare-bill-passes-after-keir-starmer-offers-late-concession"]," in July 2025 could not have been organised in a worse fashion. Talk of it being a ",["“confidence issue”","https://x.com/PolitlcsUK/status/1937508066351780216"]," was always a nonsense, real or imagined."]},{"k":"p","s":["The rebellion happened in the context of severe restrictions on the ",["winter fuel payment","https://theconversation.com/some-pensioners-are-pretty-well-off-but-how-many-can-afford-to-lose-the-winter-fuel-payment-238920"],", the government’s insistence that it was not going to scrap the two-child benefit limit and its own assessment that the benefit moves would push an estimated ",["250,000 people","https://www.bigissue.com/news/politics/labour-mps-keir-starmer-rebellion-disability-benefit-cuts/"]," into poverty. Within months of the Labour government being elected, it looked as though it had forgotten the reason for its very existence."]},{"k":"p","s":["Whatever the intention, these plans were seen to be bereft of any sense of Labour values. This time around, the world has changed. Crucially, the three key architects of the rejected policy (Starmer, his chancellor Rachel Reeves and his work and pensions secretary Liz Kendall) have all gone – banished to the back benches or off to find pastures new."]},{"k":"p","s":["The winter fuel payment was revisited and this allowance is ",["now means-tested","https://www.bbc.co.uk/news/articles/cglejl656y1o"],". The two-child benefits limit has been scrapped. An ",["anti-poverty","https://capuk.org/news-and-blog/what-are-andy-burnhams-policy-announcements-so-far"]," strategy has been articulated. Labour now has in Andy Burnham what many of the former rebels will see as a Labour PM."]},{"k":"p","s":["Crucially, the ground has been prepared and the pitch has been rolled – by the whips office, the cabinet and by Burnham. It now feels like the debate is on Labour terms, unlike last summer. It is no accident that there has been an ongoing, sometimes subterranean, debate focusing on what to do with nearly a million young people on benefits who could and perhaps should work."]},{"k":"p","s":["Milburn’s focus has been on this young cohort first and foremost – and couched in terms of working with them to ensure a productive role and meeting their expectations and aspirations. A Labour debate in Labour language. A political strategy and a government that takes its backbenchers seriously. This is miles from where it was last year. Although success is not guaranteed, the government now has a fighting chance to secure reform on its own terms – and that matters."]},{"k":"p","s":["Tony McNulty, teaching fellow and lecturer in British politics and public policy"]},{"k":"h","s":["New guarantees must be appropriate"]},{"k":"p","s":["Young people do not suddenly become Neet at 16. While Alan Milburn’s ",["focus on opportunities","https://www.gov.uk/government/publications/from-a-welfare-state-to-a-working-state-a-new-settlement-for-the-next-generation/from-a-welfare-state-to-a-working-state-a-new-settlement-for-the-next-generation"]," rather than long-term benefit dependency is to be welcomed, ",["work that my colleagues and I have done","https://www.mmu.ac.uk/about-us/faculties/health-and-education/research/projects/mine"]," on Neets suggests this is something of a blunt instrument for such a complex picture."]},{"k":"p","s":["Our findings suggest that simply ",["guaranteeing young people","https://www.bbc.co.uk/news/articles/c69vwp09d7vvo"]," work or a placement ignores any long-terms effects that they might experience as a result of years of living with unmet needs. These could include poor mental health, bullying, disrupted education or undiagnosed and unsupported special educational needs and disabilities (Send)."]},{"k":"p","s":["Read more: ",["We know which young people are most likely to end up Neet in England – but not why","https://theconversation.com/we-know-which-young-people-are-most-likely-to-end-up-neet-in-england-but-not-why-295498"]]},{"k":"p","s":["Our five-year study, ",["Mapping interventions for Neet young people in England","https://mcrmetropolis.uk/mapping-interventions-for-neet-young-people-in-england/"],", shows that the quality of support matters. Milburn’s proposal guarantees eligible young people a fully funded, six-month job. But there is an important difference between providing meaningful opportunities and requiring young people to participate in something that does not meet their needs. If education, training or employment pathways are poorly matched to a young person’s circumstances, the risk is that they’re left feeling frustrated and disengaged. This will not improve outcomes for anyone."]},{"k":"p","s":["The report includes proposals for a “youth allowance” to replace personal independence payments (Pip) for under-25s and the health element of universal credit. But lasting change requires more than welfare reform alone. Alongside employment support, there needs to be less rigidity and less focus on exam outcomes in secondary schools. There’s also a wider need for better mental health provision and stronger support for young people whose needs have too often gone unrecognised. An “opportunity guarantee” can only work if the opportunities themselves are genuinely inclusive and supportive."]},{"k":"p","s":["Lisa Russell, professor of education and employment"]},{"k":"h","s":["Previous policy hasn’t helped young workers"]},{"k":"p","s":["There are many costs to employing a worker, beyond the headline hourly or annual wage. The increase in employers’ national insurance contributions last year for workers aged 21 or over was just one in a series of these rises. There were also increases in 2019 to the automatic enrolment pension contributions that employers have to make, and sick pay was improved in 2016 as part of the Employment Rights Act. These costs are all linked to wages, so when wages increase, the cost of national insurance, pensions and benefits such as sick pay increase as well."]},{"k":"p","s":["This is exactly what happened when Labour lowered the age limit for the national living wage from 25 to 21 in 2024. Employers often attempt to ",["pass on their extra costs","https://ifs.org.uk/articles/labours-policies-workers-rights-and-mandated-workplace-benefits"]," to workers by paying them lower wages. If this isn’t possible (because of a rising minimum wage), they may instead reduce hiring. In some cases, they may choose not to employ a young worker at all."]},{"k":"p","s":["By proposing to abolish employers’ national insurance contributions for workers aged under 25, and recommending that automatic pension enrolment should not be expanded further, Alan Milburn has recognised this issue. The proposed cut in national insurance contributions is targeted at employers in retail and hospitality. These sectors employ many young people, often on the minimum wage. As a result, the joint effects of a rising minimum wage and increases in other costs are greater than in other sectors. Young people’s job prospects may have suffered as a result."]},{"k":"p","s":["Rachel Scarfe, lecturer in economics"]},{"k":"h","s":["Employers should resist AI"]},{"k":"p","s":["There is an economic reason to believe that AI is negatively affecting the entry-level jobs that young people typically apply for. Ultimately, a fundamental change is required. Both young and old people should be advised to have a basic understanding of AI and integrating it into their workplace. Much like with the introduction of computers decades ago, it’s fair to expect that everybody will be required to work with AI to some extent."]},{"k":"p","s":["However, many entry-level positions are defined by repetitive, standardised work – or ",["commodity work","https://theconversation.com/the-more-commodified-your-job-the-more-likely-ai-can-do-it-lessons-from-online-freelancing-280236"]," – for example, writing emails and memos or preparing presentation slides. AI does these tasks easily, making it a short-term economic incentive for companies to replace their junior workers with AI, and contributing to the Neet issue. Similarly, with ",["“AI-washing”","https://www.bbc.co.uk/news/articles/c9xx8122893o"],", companies can let go of junior employees while using AI as a scapegoat."]},{"k":"p","s":["However, from my point of view, the problem is much more far-reaching. Companies are cutting off their own talent pipeline by not investing in junior workers, as they will not have experts five or ten years down the road. This will have dramatic consequences, as experts are needed more, not less, when it comes to AI. Firms would see long-term gain if they invested in developing young people’s skills."]},{"k":"p","s":["To escape this dilemma, the government should do everything it can to incentivise firms to focus on the human. Though it can cost employers when young people make mistakes while they’re learning, companies should instead speed up the process of building staff expertise in using AI."]},{"k":"p","s":["Fabian Stephany, lecturer in AI and work"]}],"chars":7925},"https://www.gov.uk/foreign-travel-advice/france":{"r":"govuk","at":"2026-11-17T16:38Z","sha":"fb8ce01ff09ca3cd0e5f2143ab50ff193854cd9b58706c195beba5b0ca7d43ab","read":"https://www.gov.uk/api/content/foreign-travel-advice/france","bytes":134435,"x":"fulltext v1","title":"France travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-18T15:33:05+00:00","mod":"2026-10-22T17:57:33+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Demonstrations"]},{"k":"p","s":["There is an increased likelihood of demonstrations, political gatherings and marches taking place across France, sometimes at short notice."]},{"k":"p","s":["Whilst most demonstrations are peaceful, you should remain aware of your surroundings. Stay away from areas with large crowds or a significant police presence, and follow the advice of police and local authorities."]},{"k":"p","s":["Demonstrations may disrupt local transport services and authorities may impose public safety measures, including partial and localised curfews in some areas. Monitor local media for the latest information about measures in your area."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth and Development Office (FCDO) provides advice about the risks of travel, to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/france/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in France set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["French Embassy in the UK","https://uk.ambafrance.org/Contact-Us-24150"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["France follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the date you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes France, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The ",["requirements for working in France","https://www.gov.uk/guidance/travel-to-france-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day visa-free limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["If you cannot return to the UK before your visa-free limit expires, contact the nearest ",["local prefecture in France","https://www.interieur.gouv.fr/Le-ministere/Prefectures"],"."]},{"k":"p","s":["At French border control, you may be asked to:"]},{"k":"li","s":["show proof of your travel insurance to demonstrate you can cover any emergency costs"]},{"k":"li","s":["prove that you have ",["enough money for your stay","https://france-visas.gouv.fr/en/votre-arrivee-en-france"]]},{"k":"li","s":["show proof of your accommodation"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"hs","s":["Staying with family, friends or a third party"]},{"k":"p","s":["You may be asked to provide a welcome invitation (‘attestation d’accueil’) from your host. The French resident hosting you must get the ",["attestation d’accueil","https://www.service-public.fr/particuliers/vosdroits/F2191?lang=en"]," from their local mayor’s office and send the original attestation before you enter France."]},{"k":"hs","s":["Second homes in France"]},{"k":"p","s":["You may need to show evidence of ownership or tenancy of your property, such as a tax or utility bill."]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer than 90 days, you must meet the ",["French government’s entry requirements","https://www.service-public.fr/particuliers/vosdroits/N105?lang=en"],"."]},{"k":"p","s":["If you’re in France with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit for the Schengen area."]},{"k":"p","s":["Read about ",["entry processes if you live in France","https://www.gov.uk/guidance/living-in-france#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Border controls at Germany’s land borders"]},{"k":"p","s":["There are temporary border controls in place to travel into Germany. Check the ",["entry requirements for Germany","https://www.gov.uk/foreign-travel-advice/germany/entry-requirements"],"."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s France guide","https://travelhealthpro.org.uk/country/81/france#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of France","https://www.douane.gouv.fr/fiche/volume-and-value-based-customs-and-tax-allowances"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food and drink into France"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into France"]},{"k":"p","s":["Declare cash or travellers cheques if the value is 10,000 euros or more. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in France"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in France."]},{"k":"p","s":["Terrorism attacks could be indiscriminate, including in places visited by tourists and foreign nationals such as:"]},{"k":"li","s":["shopping centres"]},{"k":"li","s":["entertainment establishments and nightlife venues"]},{"k":"li","s":["sporting and cultural events"]},{"k":"li","s":["public transport and national and international transport hubs"]},{"k":"li","s":["places of worship"]},{"k":"li","s":["crowded places and public gatherings"]},{"k":"p","s":["Methods of attack have included knife attacks, shootings, bombings and vehicle attacks. Be vigilant in public places and follow the advice of local French authorities."]},{"k":"p","s":["There have been several recent high-profile terrorist attacks in France, including:"]},{"k":"li","s":["in 2023, one person was killed in a knife and hammer attack in central Paris"]},{"k":"li","s":["in 2023, a teacher was killed in a knife attack in a school in Arras"]},{"k":"p","s":["French authorities regularly report that they have disrupted planned attacks and made arrests."]},{"k":"h","s":["Industrial action and demonstrations"]},{"k":"hs","s":["Industrial action"]},{"k":"p","s":["There can be frequent industrial action across France. This can lead to disruption and delays on roads and public transport. If you’re due to travel to or within France, monitor the media, check your operator’s advice and follow the advice of the authorities."]},{"k":"p","s":["Check your operator’s advice before travelling, including where you are taking connecting flights."]},{"k":"hs","s":["Demonstrations"]},{"k":"p","s":["Demonstrations, political gatherings, or marches can take place with little or no warning, particularly in cities."]},{"k":"p","s":["Whilst most demonstrations are peaceful, if you’re near areas where they are taking place, you should remain aware of what is happening around you and follow the advice of the police and local authorities."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Take sensible precautions against street crime and car crime. Pickpockets can work in gangs; one distracts you while the other one goes into your bag."]},{"k":"p","s":["Thieves and pickpockets operate on the Paris Métro, on RER (train) lines and at mainline stations. To reduce the risk of theft:"]},{"k":"li","s":["keep your passport, credit cards and other valuables in separate bags or pockets"]},{"k":"li","s":["use the inside compartments in bags where possible"]},{"k":"li","s":["carry your bag across your body rather than on your shoulder"]},{"k":"li","s":["keep your belongings close to you in restaurants and bars"]},{"k":"li","s":["do not leave any valuables in your vehicle"]},{"k":"li","s":["do not get distracted around tourist attractions and ATMs"]},{"k":"hs","s":["Assaults"]},{"k":"p","s":["There have been several cases of serious assault on the RER line B, which serves:"]},{"k":"li","s":["Paris Charles de Gaulle airport"]},{"k":"li","s":["Orly Airport"]},{"k":"li","s":["Paris Gare du Nord Eurostar terminus"]},{"k":"p","s":["There have also been serious assaults on RER line D, which serves the Stade de France."]},{"k":"hs","s":["Drink spiking and sexual assault"]},{"k":"p","s":["Be alert to the possible use of ‘date rape’ and other drugs including GHB and liquid ecstasy."]},{"k":"p","s":["Buy your own drinks and always keep them in sight to avoid them being spiked. Alcohol and drugs can reduce your vigilance, making you less in control. If you drink, know your limit. Drinks served in bars in France are often stronger than those in the UK."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You must be able to ",["prove your identity","https://www.service-public.fr/particuliers/vosdroits/F1036?lang=en"]," by providing documents when asked or within 4 hours at a police station. Accepted IDs are:"]},{"k":"li","s":["passport"]},{"k":"li","s":["photocard driving licence"]},{"k":"li","s":["other documentation provided by a government body"]},{"k":"hs","s":["Face-covering ban"]},{"k":"p","s":["Covering your face in public places in France is illegal. This includes balaclavas, full veils or any other garment or mask that is used to hide the face. You could get a fine of up to 150 euros if you do not comply."]},{"k":"p","s":["Forcing someone to hide their face is also a crime and is punishable by a year’s imprisonment and a fine of up to 30,000 euros. If the person forced to hide their face is aged 17 and under, the sentence is doubled. This law applies to tourists."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, carry severe penalties including imprisonment and heavy fines for possessing, using or smuggling illegal drugs, including when transiting through airports, ports and Eurostar stations."]},{"k":"p","s":["Airports, ports and Eurostar stations in France have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Local sea conditions can be dangerous even for strong swimmers. Most beaches have lifeguards and flag warning systems. Make sure you understand the warning system before swimming and always follow the advice closely. See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"p","s":["Some beaches have strong undercurrents, especially along the Atlantic coast. There is a risk of riptides (‘baïnes’) in some areas, particularly around the coast of Gironde and Landes."]},{"k":"p","s":["Follow local advice if there are jellyfish in the sea."]},{"k":"hs","s":["Watersports"]},{"k":"p","s":["Before taking part in water-based activities, find out how you and your friends or family will be supervised and supported."]},{"k":"p","s":["See ⁠ ",["watersports safety advice","https://www.rospa.com/leisure-water-safety/water/advice/watersports-abroad"]," from the Royal Society for the Prevention of Accidents (ROSPA)."]},{"k":"hs","s":["Trekking and mountaineering"]},{"k":"p","s":["Check weather forecasts and conditions and make sure you’re properly prepared. Do not undertake any activity alone and consider hiring a guide for expert advice. Always leave copies of your itinerary with someone."]},{"k":"p","s":["In mountainous areas, make sure your insurance covers you for extra costs such as mountain rescue service and helicopter evacuation. In the départements of Savoie and Haute-Savoie, you may need to be transferred to Switzerland for treatment."]},{"k":"hs","s":["Winter sports"]},{"k":"p","s":["Read advice on how to ",["prepare for winter sports","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],". Check ",["current weather forecasts and avalanche risks","https://meteofrance.com/meteo-montagne"]," on the Meteo France website and consider carrying avalanche search equipment if you ski off-piste."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in France, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s France guide","https://www.rac.co.uk/drive/travel/country/france/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in France. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],". These have replaced GB stickers."]},{"k":"p","s":["If you are visiting France, you may be able to use your ",["Blue Badge","https://www.gov.uk/government/publications/blue-badge-using-it-in-the-eu/using-a-blue-badge-in-the-european-union"]," in some circumstances. Check local parking rules."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"hs","s":["Penalties"]},{"k":"p","s":["Police give you on-the-spot fines for driving offences, including speeding."]},{"k":"p","s":["France has strict drink-driving laws and the legal alcohol limit is a third lower than the limit for England and Wales. Police regularly carry out roadside checks for alcohol and drugs. Penalties include fines, loss of licence and prison."]},{"k":"hs","s":["Winter tyres and chains"]},{"k":"p","s":["Vehicles driven in certain mountain regions during the winter period (1 November to 31 March) must be fitted with winter tyres or chains. You could receive a fine if you do not comply. Visit the ",["French public services website","https://www.service-public.fr/particuliers/actualites/A14389?lang=en"]," for more information (in English) about:"]},{"k":"li","s":["what type of vehicle this applies to"]},{"k":"li","s":["what type of tyre or chain should be fitted"]},{"k":"li","s":["where in France these rules apply."]},{"k":"hs","s":["Air pollution sticker"]},{"k":"p","s":["All vehicles driving in central Paris, Lyon and Grenoble must display a pollution sticker from 8am to 8pm, Monday to Friday. Checks can happen at any time, depending on pollution levels."]},{"k":"p","s":["Some older vehicles do not qualify for a sticker at all due to their high emissions. These vehicles must not be driven in central Paris from 8am to 8pm, Monday to Friday."]},{"k":"p","s":["Other cities may also limit vehicle access to town centres and main roads. For more information or to apply for a sticker, visit the ",["French Ministry of Environment website","https://www.certificat-air.gouv.fr/en/"],"."]},{"k":"hs","s":["Road safety"]},{"k":"p","s":["If you’re involved in a car accident or witness an accident on the motorway, use the orange emergency phones to ask for help."]},{"k":"p","s":["If you are driving long distances in France:"]},{"k":"li","s":["plan your journey carefully"]},{"k":"li","s":["take into account unknown roads, weather conditions and fatigue"]},{"k":"li","s":["take regular breaks"]},{"k":"p","s":["Keep vehicle doors locked in slow-moving traffic and secure your vehicle if you leave it unattended."]},{"k":"p","s":["Information on road safety and potential traffic black spots is available on the Bison Futé website (in French). Real-time information on road traffic conditions is also available on Motorways Radio: 107.7 FM in French and in English."]},{"k":"hs","s":["Risk of people entering your vehicle"]},{"k":"p","s":["There have been attempts by people to enter private vehicles with a view to entering the UK illegally. They may target vehicles like camper vans while stationary or in slow-moving traffic. Sometimes people might try to slow down traffic on roads to ports, including by placing obstacles on the Calais Port road."]},{"k":"p","s":["Keep car doors locked, keep moving where it’s safe to do so, and do not leave your vehicle unattended. If it is not safe to proceed, stop and call 112."]},{"k":"p","s":["Commercial transport firms must take ",["steps to prevent people from entering their vehicles","https://www.gov.uk/government/publications/preventing-clandestine-entrants"],"."]},{"k":"hs","s":["Thefts from caravans and camper vans"]},{"k":"p","s":["Burglaries can happen while you are asleep in your vehicle. Take sensible precautions against vehicle break-ins. You should:"]},{"k":"li","s":["avoid parking in isolated or dark areas of unsupervised camping grounds or car parks"]},{"k":"li","s":["consider installing an alarm"]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Extreme temperatures"]},{"k":"p","s":["In summer months, there is a risk of higher than normal temperatures in France. Check current weather forecasts and read about how to protect yourself on the ",["Meteo France website","https://vigilance.meteofrance.fr/fr"],"."]},{"k":"p","s":["Find advice on how to stay safe in hot weather from the ",["National Health Service (NHS)","https://www.nhs.uk/live-well/seasonal-health/heatwave-how-to-cope-in-hot-weather/"],"."]},{"k":"p","s":["Check with your travel provider and follow advice from local authorities."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Wildfires can occur across France during the summer months. The risk is highest in the south of the country, particularly along the Mediterranean coast, in Corsica, and in areas of the south-west during periods of hot, dry weather."]},{"k":"p","s":["Check the French weather service’s ",["fire alert map","https://meteofrance.com/meteo-des-forets"]," before travelling and monitor local authority advice during your stay. Conditions can change quickly and access to forests, countryside areas and tourist sites may be restricted at short notice."]},{"k":"p","s":["Fires have become more frequent because of drought and high temperatures. French authorities may evacuate areas and close roads for safety reasons. Causing a wildfire is ",["illegal in France","https://eur03.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.service-public.fr%2Fparticuliers%2Fvosdroits%2FF34031%3Flang%3Den&data=05%7C02%7CMimi.Leicester%40fcdo.gov.uk%7Ccfb7ed24c072413c065608ddcf36443e%7Cd3a2d0d37cc84f52bbf985bd43d94279%7C0%7C0%7C638894554159618684%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&sdata=dUv16ItWwVru2f8FyANmyzoTZJC6Nt7HTVniamNaptU%3D&reserved=0%22%20\\o%20%22https://eur03.safelinks.protection.outlook.com/?url=https%3a%2f%2fwww.service-public.fr%2fparticuliers%2fvosdroits%2ff34031%3flang%3den&data=05%7c02%7cmimi.leicester%40fcdo.gov.uk%7ccfb7ed24c072413c065608ddcf36443e%7cd3a2d0d37cc84f52bbf985bd43d94279%7c0%7c0%7c638894554159618684%7cunknown%7ctwfpbgzsb3d8eyjfbxb0eu1hcgkionrydwusilyioiiwljaumdawmcisilaioijxaw4zmiisikfoijoitwfpbcisilduijoyfq%3d%3d%7c0%7c%7c%7c&sdata=duv16itwwvru2f8fyanmyzotzjc6nt7htvniamnaptu%3d&reserved=0%22%20\\t%20%22_blank"],", even if it is started by accident. You could get a fine or a prison sentence."]},{"k":"p","s":["If you’re staying in, or near, a high-risk area see advice from the ",["French government","https://eur03.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.ecologie.gouv.fr%2Fen%2Fforest-fires-and-wildfires%23what-to-do-in-case-of-a-fire-outbreak-0&data=05%7C02%7CMimi.Leicester%40fcdo.gov.uk%7Ccfb7ed24c072413c065608ddcf36443e%7Cd3a2d0d37cc84f52bbf985bd43d94279%7C0%7C0%7C638894554159643193%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&sdata=%2BKFSrsIru%2B4JCMoMpDGD4ryPXoiVceXqxLBvcjlO14Y%3D&reserved=0%22%20\\o%20%22https://eur03.safelinks.protection.outlook.com/?url=https%3a%2f%2fwww.ecologie.gouv.fr%2fen%2fforest-fires-and-wildfires%23what-to-do-in-case-of-a-fire-outbreak-0&data=05%7c02%7cmimi.leicester%40fcdo.gov.uk%7ccfb7ed24c072413c065608ddcf36443e%7cd3a2d0d37cc84f52bbf985bd43d94279%7c0%7c0%7c638894554159643193%7cunknown%7ctwfpbgzsb3d8eyjfbxb0eu1hcgkionrydwusilyioiiwljaumdawmcisilaioijxaw4zmiisikfoijoitwfpbcisilduijoyfq%3d%3d%7c0%7c%7c%7c&sdata=%2bkfsrsiru%2b4jcmompdgd4rypxoivcexqxlbvcjlo14y%3d&reserved=0%22%20\\t%20%22_blank"]," (in English) for information about:"]},{"k":"li","s":["what to do if a wildfire breaks out"]},{"k":"li","s":["how to prevent wildfire outbreaks"]},{"k":"li","s":["protecting your home from wildfires (including mandatory bush clearance)"]},{"k":"p","s":["If you are caught in, or witness, a wildfire, call the emergency services on 18 (fire) or 112 (emergency services)."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["There is a risk of flooding in areas of France. If your accommodation is near a river, check flash flood watch (‘vigicrues’) (in French) for more information on current flood risks."]},{"k":"hs","s":["Avalanches"]},{"k":"p","s":["There is a risk of avalanches in mountainous areas. Check ",["current weather forecasts and avalanche risks","https://meteofrance.com/meteo-montagne"]," on the Meteo France website. Follow local advice before you ski or hike and consider carrying avalanche search equipment."]},{"k":"p","s":["Conditions on roads in mountainous areas can quickly become difficult in winter. Carry water, food, warm clothing and medicines in your vehicle."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for France","https://travelhealthpro.org.uk/country/81/france#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See what ",["health risks you’ll face in France","https://travelhealthpro.org.uk/country/81/france"],", including:"]},{"k":"li","s":["dengue"]},{"k":"li","s":["chikungunya"]},{"k":"li","s":["biting insects and ticks"]},{"k":"p","s":["Altitude sickness is a risk in parts of France. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in France"]},{"k":"p","s":["FCDO has a list of ",["hospitals in major cities including Paris, Marseille and Bordeaux region","https://www.gov.uk/guidance/france-medical-facilities"]," where some staff will speak English."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in France, you need a Global Health Insurance Card (GHIC) or a valid existing European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["State healthcare in France is not always free. Treatment is on the same basis as for French citizens."]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in France","https://www.gov.uk/guidance/healthcare-in-france-including-martinique-and-guadaloupe"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in France"]},{"k":"p","s":["Telephone 112 (ambulance, fire, police)"]},{"k":"p","s":["Ambulance: 15"]},{"k":"p","s":["Fire: 18"]},{"k":"p","s":["Police: 17"]},{"k":"p","s":["Deaf and hard of hearing emergency number (SMS, chat, video and fax): 114"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=France"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=France"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=France"]," in France"]},{"k":"li","s":["dealing with a ",["death in France","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-france"]]},{"k":"li","s":["being ",["arrested in France","https://www.gov.uk/government/publications/france-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you are ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/france/british-embassy-paris"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/france/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in France","https://www.gov.uk/government/publications/overseas-business-risk-france"]," on how to manage political, economic, and business security-related risks."]}],"chars":23875,"change":"Updated information about demonstrations (‘Warnings and insurance’ page)."},"https://theconversation.com/salam-tiga-jari-menjadi-simbol-masyarakat-sedang-lapar-apbn-yang-adil-296131":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"7126fca3fbf70dc0a3da2bb4b401b5f1d18b1f6a7f9fedd0dc9d060fda98897d","read":"https://theconversation.com/salam-tiga-jari-menjadi-simbol-masyarakat-sedang-lapar-apbn-yang-adil-296131","bytes":185674,"x":"fulltext v1","title":"Salam tiga jari menjadi simbol masyarakat sedang “lapar” APBN yang adil","by":[{"n":"Septian Bayu Kristanto","r":"Research associate professor, Center of Tax and Accounting Studies, Universitas Kristen Krida Wacana"}],"pub":"2026-11-09T06:00:08Z","mod":"","blocks":[{"k":"p","s":["• Gerakan salam tiga jari sedang jadi tren yang banyak dilakukan oleh berbagai lapisan masyarakat."]},{"k":"p","s":["• Pemerintah dinilai tidak berpihak pada rakyat di tengah kondisi sulit seperti sekarang."]},{"k":"p","s":["• Bukan tidak mungkin aksi solidaritas ini kian membesar ke depannya."]},{"k":"p","s":["Belakangan ini gerakan mengacungkan tiga jari sebagai simbol solidaritas antarmasyarakat sangat terlihat. Hal ini tak lepas dari momen Peringatan Hari Sumpah Pemuda pada 28 Oktober 2026 yang penuh dinamika dan melahirkan tagar ",["#IndonesiaSadar","https://www.amnesty.id/kabar-terbaru/siaran-pers/jangan-represi-dengarkan-aspirasi-indonesiasadar/10/2026/"],"."]},{"k":"p","s":["Simbol tiga jari terinspirasi dari film ",["The Hunger Games","https://tirto.id/makna-simbol-tiga-jari-di-demo-jakarta-dan-kota-lain-hEmd"],", simbol tersebut berkembang menjadi lambang solidaritas, perlawanan terhadap kekuasaan otoriter, serta perjuangan untuk kebebasan dan kesetaraan di berbagai negara."]},{"k":"p","s":["Di Indonesia, gerakan ini mencerminkan keresahan masyarakat, terutama anak muda, terhadap persoalan yang dinilai belum ditangani serius oleh negara, seperti sulitnya memperoleh pekerjaan layak, eksploitasi sumber daya alam, krisis ekologis, ketimpangan sosial, dan kesejahteraan."]},{"k":"p","s":["Jika solidaritas masyarakat diwujudkan melalui kepedulian terhadap sesama, solidaritas negara seharusnya tercermin dalam kebijakan yang memastikan akses terhadap kebutuhan dasar, kesempatan ekonomi, dan perlindungan sosial secara adil."]},{"k":"p","s":["Sejatinya, anggaran pendapatan dan belanja negara (APBN) bisa memperbaiki semua tuntutan tersebut. Menurut ",["Theory of Public Finance","https://openlibrary.org/books/OL6247802M/The_theory_of_public_finance"]," (teori keuangan publik), ada tiga fungsi utama dalam kebijakan fiskal, yaitu alokasi sumber daya, distribusi pendapatan, dan stabilisasi ekonomi."]},{"k":"p","s":["Read more: ",["Dua tahun Prabowo-Gibran: Alih-alih kreatif, program mercusuar justru berisiko menggerogoti negara","https://theconversation.com/dua-tahun-prabowo-gibran-alih-alih-kreatif-program-mercusuar-justru-berisiko-menggerogoti-negara-294595"]]},{"k":"h","s":["Beban masyarakat terus kian berat"]},{"k":"p","s":["Salah satu ironi dalam demo 28 Oktober lalu di Jakarta adalah tuntutan para demonstran, yakni “ ",["LAPAR","https://www.kompas.tv/nasional/698395/demo-28-oktober-bem-ui-ungkap-persiapan-sampai-sasaran-aksi-hari-ini"],"” atau lima perintah rakyat. Secara harfiah, lapar juga bisa mencerminkan kondisi masyarakat saat ini."]},{"k":"p","s":["Di tengah polemik program Makan Bergizi Gratis (MBG) dan bencana karhutla, masyarakat juga menghadapi tekanan ekonomi akibat kenaikan harga berbagai kebutuhan pokok. Akibatnya, memenuhi kebutuhan sehari-hari semakin membebani sebagian rumah tangga."]},{"k":"p","s":["Sejak awal tahun, beban rumah tangga keluarga masyarakat Indonesia meningkat karena beban inflasi yang diakibatkan ",["kenaikan harga minyak dunia","https://theconversation.com/beban-inflasi-juni-akibat-kenaikan-bbm-tak-terbantahkan-lagi-lampu-kuning-bagi-masyarakat-286252"],". Namun alih-alih membaik, efeknya justru kian menyebar."]},{"k":"p","s":["Salah satu yang menarik perhatian adalah kenaikan harga tepung ",["terigu dan tapioka","https://www.detik.com/jatim/bisnis/d-8714826/rupiah-sentuh-rp-18-ribu-harga-bahan-pokok-di-pasar-tradisional-naik"]," pada Oktober 2026. Laporan dari pasar di ",["Surabaya, Sidoarjo","https://www.detik.com/jatim/bisnis/d-8714826/rupiah-sentuh-rp-18-ribu-harga-bahan-pokok-di-pasar-tradisional-naik"],", dan ",["sejumlah daerah lain","https://katadata.co.id/lifestyle/varia/6ae31ae357cb6/harga-melonjak-ini-6-pengganti-tepung-tapioka-untuk-bakso-hingga-gorengan"]," menunjukkan harga tepung terigu biasa naik dari Rp200 ribu menjadi Rp213 ribu–Rp215 ribu per sak (25 kilogram)."]},{"k":"p","s":["Indonesia masih bergantung pada ",["impor gandum","https://www.bps.go.id/id/statistics-table/1/MjAxNiMx/impor-biji-gandum-dan-meslin-menurut-negara-asal"],", sehingga harga terigu rentan terhadap fluktuasi global dan pelemahan rupiah. Sementara itu, kenaikan ",["harga tapioka","https://kppu.go.id/berita/kppu-temukan-pasokan-ubi-kayu-terbatas-produksi-tapioka-di-lampung-belum-optimal"]," dipicu persoalan pasokan ubi kayu di Lampung, termasuk dugaan permainan pasar yang ditemukan Komisi Pengawas Persaingan Usaha (KPPU) pada Agustus 2026."]},{"k":"p","s":["Kenaikan harga bahan baku juga membebani UMKM, terutama sektor makanan dan olahan, karena meningkatkan biaya produksi. Artinya, persoalan harga pangan bukan sekadar soal inflasi, tetapi juga tentang beban ekonomi yang lebih berat dirasakan kelompok masyarakat tertentu."]},{"k":"p","s":["Read more: ",["Beban inflasi Juni akibat kenaikan BBM tak terbantahkan lagi: Lampu kuning bagi masyarakat","https://theconversation.com/beban-inflasi-juni-akibat-kenaikan-bbm-tak-terbantahkan-lagi-lampu-kuning-bagi-masyarakat-286252"]]},{"k":"h","s":["Tanggung jawab pemerintah"]},{"k":"p","s":["Mencari satu pihak untuk disalahkan atas kenaikan harga pangan atau karhutla tidak akan menyelesaikan persoalan. Keduanya melibatkan faktor struktural, kelembagaan, dan ekonomi yang saling berkaitan."]},{"k":"p","s":["Dalam kasus ",["tepung terigu","https://www.detik.com/jatim/bisnis/d-8714826/rupiah-sentuh-rp-18-ribu-harga-bahan-pokok-di-pasar-tradisional-naik"],", pemerintah dapat mengurangi kerentanan pasokan melalui diversifikasi impor, efisiensi logistik, dan penguatan industri pangan domestik."]},{"k":"p","s":[["Terkait tapioka","https://kppu.go.id/berita/kppu-temukan-pasokan-ubi-kayu-terbatas-produksi-tapioka-di-lampung-belum-optimal"],", pemerintah perlu memperkuat koordinasi sektor pertanian, industri pengolahan, dan tata niaga agar kepentingan petani dan industri tetap terlindungi."]},{"k":"p","s":["Sementara itu, penanganan ",["karhutla","https://tirto.id/berapa-biaya-yang-harus-dibayar-akibat-karhutla-hDfh"]," tidak cukup mengandalkan pemadaman. Pengawasan kawasan rawan, pencegahan pembakaran lahan, penegakan hukum, dan koordinasi lintas wilayah juga harus diperkuat."]},{"k":"p","s":["Artinya, pemerintah selalu memiliki ruang untuk memperbaiki keadaan melalui kebijakan yang tepat. Buku Governing the Commons karya pengamat politik Amerika Serikat ",["Elinor Ostrom","https://www.cambridge.org/core/books/governing-the-commons/7AB7AE11BADA84409C34815CC288CD79"]," menekankan pentingnya kelembagaan, pengawasan, dan tanggung jawab kolektif dalam mengelola sumber daya bersama."]},{"k":"p","s":["Dengan demikian, persoalan yang perlu dikritik bukan hanya jumlah anggaran yang tersedia, tetapi juga bagaimana anggaran tersebut diterjemahkan menjadi tindakan nyata."]},{"k":"p","s":["Read more: ",["Publik lebih menantikan perbaikan kebijakan ketimbang pergantian menteri keuangan semata","https://theconversation.com/publik-lebih-menantikan-perbaikan-kebijakan-ketimbang-pergantian-menteri-keuangan-semata-291998"]]},{"k":"h","s":["Mengembalikan makna solidaritas dalam kebijakan negara"]},{"k":"p","s":["Negara memang memiliki keterbatasan sumber daya dan harus menentukan prioritas. Namun, keterbatasan tersebut justru menuntut proses pengambilan keputusan yang lebih transparan, rasional, dan untuk kepentingan khalayak luas."]},{"k":"p","s":["Tidak ada salahnya pemerintah memiliki program mercusuar. Namun, seharusnya ",["program MBG","https://openlibrary.org/books/OL6247802M/The_theory_of_public_finance#editions-list"]," dapat menjadi instrumen investasi pembangunan manusia yang menyentuh aspek gizi, keberlanjutan, dan keadilan bagi masyarakat."]},{"k":"p","s":["Pengendalian karhutla merupakan investasi untuk menjaga keberlanjutan lingkungan dan kesehatan masyarakat. Penguatan ketahanan pangan merupakan upaya melindungi daya beli sekaligus keberlanjutan ekonomi rumah tangga dan UMKM."]},{"k":"p","s":["Evaluasi APBN tidak boleh berhenti pada besarnya anggaran atau tingginya realisasi belanja. Hal yang lebih penting adalah memastikan uang publik benar-benar menjawab kebutuhan masyarakat dan siapa yang paling diuntungkan."]},{"k":"p","s":["Salam tiga jari terlihat sederhana, tetapi pesannya jelas: tuntutan rakyat harus tercermin dalam keputusan anggaran. APBN bukan sekadar alat membiayai program pemerintah, melainkan cerminan keberpihakan negara."]},{"k":"p","s":["Pemerintah tidak cukup merespons keresahan dengan pencitraan atau pendekatan simbolis. Tanpa kebijakan yang konkret, transparan, dan berpihak pada kebutuhan publik, kepercayaan masyarakat akan terus tergerus. Legitimasi pemerintah tidak cukup dibangun melalui mandat elektoral, tetapi harus dibuktikan melalui kesejahteraan yang benar-benar dirasakan rakyat."]},{"k":"p","s":["Pemerintah mungkin memiliki mandat untuk menentukan prioritas pembangunan, tetapi masyarakat memiliki hak untuk menilai apakah prioritas tersebut benar-benar mencerminkan kepentingan publik."]}],"chars":6257},"https://www.gov.uk/foreign-travel-advice/latvia":{"r":"govuk","at":"2026-11-17T17:03Z","sha":"81aced20736fbecaa6ba3f1da904858c5061a791234e85b7a8f0610423b0d8b4","read":"https://www.gov.uk/api/content/foreign-travel-advice/latvia","bytes":68367,"x":"fulltext v1","title":"Latvia travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-14T00:00:00+00:00","mod":"2026-08-11T10:17:07+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/latvia/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Latvia set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Latvian Embassy in the UK","https://www2.mfa.gov.lv/en/london"],"."]},{"k":"h","s":["British-Russian dual nationals"]},{"k":"p","s":["If you hold dual nationality with Russia, you could be refused entry to Latvia. See current ",["legal guidance for Russian citizens","https://likumi.lv/ta/id/358965-noteikumi-par-treso-valstu-valstspiederigo-vizu-pieteikumu-pienemsanas-un-iecelosanas-ierobezojumiem-latvijas-republika"],", which is now in force until 1 January 2027."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Latvia follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["have an ‘expiry date’ at least 3 months after the day you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Latvia, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The ",["requirements for working in Latvia","https://www.gov.uk/guidance/travel-to-latvia-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day visa-free limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Latvian border control, you may need to:"]},{"k":"li","s":["show proof of your accommodation, for example, a hotel booking confirmation or proof of address for a second home"]},{"k":"li","s":["show proof of your travel insurance, including health cover and medical repatriation"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, you must meet the Latvian government’s entry requirements. Check which type of visa you need with the ",["Latvian Embassy in the UK","https://www2.mfa.gov.lv/en/london"],"."]},{"k":"p","s":["If you’re in Latvia with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Latvia","https://www.gov.uk/guidance/living-in-latvia#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Latvia guide","https://travelhealthpro.org.uk/country/125/latvia#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Latvia","https://www.vid.gov.lv/en/customs"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food and drink into Latvia"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into Latvia"]},{"k":"p","s":["Declare cash or travellers cheques if the value is 10,000 euros or more. You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"hs","s":["Restrictions on third-country vehicles"]},{"k":"p","s":["Any vehicle registered in third countries, including the UK, must be declared for use in Latvia via the ",["e-services","https://e.csdd.lv/trvalstutldeklar/"]," of the Road Traffic Safety Directorate before entering Latvia. No fee will be charged for the service and it can be done without personal authentication, but the e-mail address used will have to be verified. See ",["Latvia’s Ministry of Foreign Affairs webpage","https://www.mfa.gov.lv/en/article/road-traffic-safety-directorate-informs-vehicles-registered-third-country-will-have-be-declared-use-road-traffic-latvia-1-january-2025"]," for more information about the declaration process."]},{"k":"p","s":["Vehicles with Russian and Belarusian plates and registration are, with a few technical exceptions, banned from entering Latvia and using Latvia’s roads. See ",["Latvia’s State Revenue Service","https://www.vid.gov.lv/en/article/persons-vehicles-registered-russian-federation-are-banned-entering-latvia?utm_source=https%3A%2F%2Fwww.mfa.gov.lv%2F"]," and ",["Latvia’s Ministry of Foreign Affairs","https://www.mfa.gov.lv/en/article/eu-sanctions-against-belarus-significantly-limit-opportunities-circumventing-sanctions-against-russia"]," for more information."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Latvia"]},{"k":"p","s":["Although there’s no recent history of terrorism in Latvia, attacks cannot be ruled out."]},{"k":"h","s":["Belarus border"]},{"k":"p","s":[["FCDO currently advises against all travel to Belarus","https://www.gov.uk/foreign-travel-advice/belarus"],". There is limited access along parts of Latvia’s border with Belarus. The Silene-Urbani road border crossing is currently closed. More border checkpoints may close or implement restrictions at short notice."]},{"k":"p","s":["Access to within 2km of the border with Belarus is limited. If you wish to enter the border area, you are required to obtain a special licence issued by the Latvian Border Guard. You should abide by this limitation at all times and follow the instructions of Latvian authorities if you are in this area."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Petty crime, particularly bag snatching and pickpocketing, is a greater risk in:"]},{"k":"li","s":["Riga Old Town"]},{"k":"li","s":["Central Market"]},{"k":"li","s":["central train and bus stations"]},{"k":"p","s":["Take extra care in these areas and:"]},{"k":"li","s":["avoid unlit streets and parks at night"]},{"k":"li","s":["stay alert if walking alone and be wary of people who approach you"]},{"k":"li","s":["keep your documents and valuables in hotel safes or somewhere secure"]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Some tourists have been charged high prices for drinks or have found fraudulent transactions on their credit and debit cards. You should:"]},{"k":"li","s":["make sure a transaction on a credit or debit card is completed in your presence"]},{"k":"li","s":["be wary of attempts to make you re-enter your PIN"]},{"k":"li","s":["get recommendations for bars and clubs from trustworthy sources"]},{"k":"hs","s":["Bank card fraud"]},{"k":"p","s":["Fraudsters can steal your card details without you noticing. Use ATMs inside banks if possible, and check ATMs on the street for signs of tampering. Keep cards in sight when paying in shops and restaurants. Read more about how to avoid bank card fraud."]},{"k":"hs","s":["Drink and food spiking"]},{"k":"p","s":["There have been instances of drink spiking in Riga and elsewhere in Latvia. Do not leave drinks unattended and be wary of accepting food and drink from strangers in bars, nightclubs and restaurants."]},{"k":"hs","s":["Theft from vehicles"]},{"k":"p","s":["Try to use car parks with CCTV. Make sure your vehicle is locked and your belongings are out of sight."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry a copy of your passport’s photo page."]},{"k":"hs","s":["Alcohol laws and bans"]},{"k":"p","s":["Drinking alcohol in public, including in parks and in the streets, is illegal. The police could arrest and fine you."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, are strictly prohibited, even in very small quantities. Severe penalties apply for possessing, using, buying, or smuggling illegal drugs, including when transiting through airports. You should expect long jail sentences of up to 10 years and heavy fines."]},{"k":"p","s":["Airports in Latvia have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Public transport"]},{"k":"p","s":["You can get on-the-spot fines for travelling on public transport without a ticket or with an unvalidated ticket. Validate your ticket with the machine as soon as you board the bus or tram."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is legal in Latvia. Same-sex unions were legalised in 2023 and will be able to take place from July 2024."]},{"k":"p","s":["While there are some LGBT+ friendly venues in larger cities, small towns and rural areas can be less accepting of LGBT+ travellers."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Latvia, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Latvia guide","https://www.rac.co.uk/drive/travel/country/latvia/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["You can drive in Latvia with a UK driving licence. If you are living in Latvia, check the ",["driving requirements for residents","https://www.gov.uk/guidance/living-in-latvia"],"."]},{"k":"p","s":["Carry your original vehicle registration documents when travelling to Latvia by car or motorcycle. If you do not have these documents, you will not be allowed to take your vehicle back out of Latvia."]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If you are visiting Latvia, you may be able to use your ",["Blue Badge","https://www.gov.uk/government/publications/blue-badge-using-it-in-the-eu/using-a-blue-badge-in-the-european-union"]," in some circumstances. Check local parking rules."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience or a higher minimum age."]},{"k":"hs","s":["Taxi safety"]},{"k":"p","s":["To reduce the risk of being charged inflated fares:"]},{"k":"li","s":["organise a ride with a major taxi company such as Baltic Taxi or Red Cab"]},{"k":"li","s":["hail or go to a taxi rank to find an official registered vehicle with yellow licence plates"]},{"k":"li","s":["agree the approximate price of the journey before setting off – some visitors have reported meters being adapted to clock up higher rates"]},{"k":"hs","s":["Drone activity"]},{"k":"p","s":["Some Ukrainian drones aimed at Russia have crossed into Latvian airspace. Follow official guidance as necessary."]},{"k":"h","s":["Extreme weather"]},{"k":"hs","s":["Winter"]},{"k":"p","s":["Be prepared for extremely cold and possibly hazardous weather if you travel to Latvia in the winter – between October and March. Temperatures may drop to -25°C or below. Snowfalls can result in delays and cancellations on public transport and difficult road conditions."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 113 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Latvia","https://travelhealthpro.org.uk/country/125/latvia#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See what ",["health risks you’ll face in Latvia","https://travelhealthpro.org.uk/country/125/latvia"],", including tick bites during the warm season between March and October. Tick bites occasionally carry diseases like encephalitis and Lyme disease."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Latvia"]},{"k":"p","s":["FCDO has a list of ",["medical facilities in Latvia","https://www.gov.uk/government/publications/latvia-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Latvia, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Latvia","https://www.gov.uk/guidance/healthcare-in-latvia"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Latvia"]},{"k":"p","s":["Ambulance: 113"]},{"k":"p","s":["Fire: 112"]},{"k":"p","s":["Police: 110"]},{"k":"p","s":["Riga Tourist Police: +371 6718 1818"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Latvia"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Latvia"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Latvia"]," in Latvia"]},{"k":"li","s":["dealing with a ",["death in Latvia","https://www.gov.uk/government/publications/latvia-bereavement-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in Latvia","https://www.gov.uk/government/publications/latvia-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/latvia/british-embassy-riga"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/latvia/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Latvia","https://www.gov.uk/government/publications/overseas-business-risk-latvia"]," on how to manage political, economic, and business security-related risks."]}],"chars":16950,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."},"https://theconversation.com/midterms-aux-etats-unis-quelles-consequences-pour-la-guerre-en-ukraine-296063":{"r":"conversation","at":"2026-11-17T17:32Z","sha":"58dd4b8fe08641a5eb4b33b73de8a3901759a0a9c4c18d106b2795ea9e81bc39","read":"https://theconversation.com/midterms-aux-etats-unis-quelles-consequences-pour-la-guerre-en-ukraine-296063","bytes":183684,"x":"fulltext v1","title":"Midterms aux États-Unis : quelles conséquences pour la guerre en Ukraine ?","by":[{"n":"Michael Cox","r":"Founding Director of LSE IDEAS and Emeritus Professor of International Relations, London School of Economics and Political Science"}],"pub":"2026-11-06T10:34:04Z","mod":"","blocks":[{"k":"p","s":["L’ESSENTIEL"]},{"k":"li","s":["Aux États-Unis, les élections de mi-mandat ont infligé un revers cinglant à Donald Trump et aux républicains au Congrès."]},{"k":"li","s":["Peu de commentateurs croient que ce résultat changera beaucoup la politique de Trump envers l’Ukraine."]},{"k":"li","s":["Un accord entre « grandes puissances » sans Kiev se heurterait presque à coup sûr aux démocrates du Congrès."]},{"k":"p","s":["Les élections de mi-mandat ont modifié le rapport de force au Congrès des États-Unis, infligeant un revers cinglant à Donald Trump et à son Parti républicain. Ce résultat aura des conséquences dans le pays et peut-être aussi à l’étranger, notamment pour la politique de Washington envers l’Ukraine, un sujet quasiment absent des campagnes."]},{"k":"p","s":["Mais si l’ ",["Ukraine","https://theconversation.com/fr/topics/ukraine-21219"]," a peu pesé dans le scrutin, la question de l’attitude à adopter face à la guerre n’a pas disparu de la vie politique états-unienne. De fait, dans les semaines et les mois qui ont précédé l’annonce des résultats, Trump s’était employé à revenir sur le soutien des États-Unis à l’Ukraine. Il l’a fait malgré une forte opposition, y compris dans les rangs républicains."]},{"k":"p","s":["La transmission à Kiev de renseignements cruciaux sur les frappes russes ",["a été interrompue","https://www.bbc.co.uk/news/articles/cm2d6e62p49do"],", avant d’être rétablie, tandis qu’une ",["aide militaire essentielle","https://www.telegraph.co.uk/world-news/2026/10/20/white-house-blocks-transfer-of-patriot-missiles-to-ukraine/"]," était réduite. Trump a aussi ",["décidé de suspendre","https://www.bbc.co.uk/news/articles/c9p8gz7zx4peo"]," plusieurs sanctions visant la Russie."]},{"k":"p","s":["Le président ukrainien Volodymyr Zelensky a ",["dénoncé","https://www.nbcnews.com/politics/trump-administration/trump-suspends-new-russia-sanctions-deal-purchase-diesel-citing-nation-rcna603991"]," cette décision, qui selon lui ne profite qu’à la Russie, tandis que Trump l’a justifiée en invoquant « l’intérêt national des États-Unis », en y voyant aussi un moyen d’améliorer les chances électorales de son parti grâce à une baisse des prix de l’essence."]},{"k":"p","s":["Au bout du compte, rien de tout cela n’a servi Trump et les républicains. Pourtant, rares sont les commentateurs qui pensent que les résultats des élections de mi-mandat, aussi désastreux soient-ils pour lui, auront un effet notable sur sa vision de la politique étrangère, et en particulier sur sa politique envers l’Ukraine."]},{"k":"p","s":["« La politique étrangère de l’administration Trump est comme une voiture lancée sur l’autoroute », ",["expliquait","https://www.theparliamentmagazine.eu/news/article/the-democrats-won-americas-midterms-that-wont-alter-trumps-position-on-ukraine-or-europe"]," récemment James Green, chercheur au Centre for European Reform et ancien collaborateur parlementaire à Washington. « Le Congrès peut ralentir cette voiture, peut-être l’obliger à mettre son clignotant, mais il lui sera très difficile de modifier l’itinéraire d’ensemble au cours des deux prochaines années. »"]},{"k":"p","s":["Cela tient en partie à la façon dont la politique étrangère se décide aux États-Unis. Le Congrès n’est pas dépourvu d’influence. Il peut organiser des auditions, convoquer sous peine de sanctions des responsables de l’exécutif et exercer son contrôle sur le budget. Mais en tant que commandant en chef et chef de l’État, épaulé par une vaste administration consacrée à la politique étrangère, le président conserve d’importants ",["pouvoirs dans ce domaine","https://theconversation.com/midterms-apres-la-deroute-des-republicains-le-monde-doit-se-preparer-a-un-trump-plus-imprevisible-295885"],"."]},{"k":"p","s":["Il est également peu probable que les démocrates placent l’Ukraine au premier plan après ces élections. Ils auront d’autres chats à fouetter, à commencer par la nécessité de trouver un candidat et un programme capables de leur faire gagner la Maison-Blanche en 2028."]},{"k":"p","s":["L’Ukraine est pourtant une cause que de nombreux démocrates, et bon nombre de républicains, défendent depuis un certain temps. Ils ne risquent pas non plus d’oublier ce que les Américains ordinaires pensent de la Russie et de son dirigeant, Vladimir Poutine."]},{"k":"p","s":["La guerre en Ukraine n’occupe peut-être pas leurs pensées au quotidien. En revanche, comme l’a montré le ",["Pew Research Center","https://www.pewresearch.org/global/2025/04/17/how-americans-view-russia-and-putin/"]," en 2025, 67 % des États-uniens se méfient de Poutine et six sur dix considèrent la Russie comme un ennemi."]},{"k":"p","s":["Les démocrates ne souhaitent peut-être pas se retrouver entraînés dans une guerre européenne. Mais alors qu’ils viennent de remporter une victoire écrasante, ils pourraient bien estimer qu’ils ont désormais beaucoup à gagner politiquement à durcir leurs attaques contre un Trump affaibli, si sa politique étrangère envers la Russie et l’Ukraine continue, à leurs yeux, de récompenser l’agresseur tout en faisant passer la victime de cette agression pour un obstacle à un règlement du conflit."]},{"k":"h","s":["Vers un accord de paix ?"]},{"k":"p","s":["Si le résultat des élections offre aux démocrates une série d’occasions tout en mettant Trump en difficulté, il ouvre aussi une possible fenêtre à Poutine. Le dirigeant russe pourrait bien chercher à exploiter la situation politique intérieure de Trump en proposant une forme de règlement qui permettrait au président états-unien de crier victoire."]},{"k":"p","s":["Des responsables états-uniens, chinois et russes ",["discutent déjà","https://www.independent.co.uk/voices/putin-trump-china-xi-russia-moscow-washington-banquet-b3056361.html"]," d’un sommet qui se tiendrait lors du déplacement des chefs d’État en Chine pour le sommet de la Coopération économique pour l’Asie-Pacifique (Apec), en novembre. Le porte-parole du Kremlin, Dmitri Peskov, ",["a indiqué que la Russie","https://www.reutersconnect.com/collection/kremlin-hopes-plans-for-us-russia-china-leaders-meeting-will-be-finalised-soon/dGFnOnJldXRlcnMuY29tLDIwMjY6bmV3c21sX1ZBNTI4MDAzMTEyMDI2UlAx"]," espérait arrêter les modalités de cette rencontre dans les prochains jours."]},{"k":"p","s":["Trump tient lui aussi à cette rencontre. Il a déclaré aux journalistes en octobre que l’Ukraine y serait abordée, ",["ajoutant","https://www.politico.eu/article/moscow-is-helping-arrange-us-russia-china-meeting-spokesperson-peskov-says/"],": « Je participerais à une rencontre pour… tout ce que je peux faire pour mettre fin à la guerre, que quelqu’un soit là ou non, tout ce que je peux faire pour mettre fin à la guerre. »"]},{"k":"p","s":["Cela peut sembler assez raisonnable. Toutefois, décider du sort d’un pays souverain absent de la table des négociations, et conclure une sorte d’ ",["accord entre « grandes puissances »","https://theconversation.com/why-trump-xi-and-putin-cant-carve-up-the-world-like-the-big-three-leaders-of-1945-295632"]," avec deux pays autoritaires, qui prévoirait la perte de 20 % de son territoire par l’Ukraine, est presque à coup sûr une chose que les démocrates du Congrès, enhardis, ne laisseront pas passer sans réagir."]},{"k":"p","s":["Selon la plupart des experts militaires, il ne serait pas sage non plus de concéder quoi que ce soit à la Russie alors que sa guerre contre l’Ukraine semble s’être enlisée. D’après l’Institute for the Study of War, ",["la Russie a peut-être","https://understandingwar.org/research/russia-ukraine/the-myth-of-inevitable-russian-victory/"]," « pris un avantage temporaire dans le ciel ukrainien grâce à ses drones à réaction et à la pénurie de missiles Patriot capables d’intercepter ses missiles balistiques »."]},{"k":"p","s":["Mais comme le souligne aussi l’institut, à moins que l’aide militaire occidentale ne se tarisse complètement, une victoire russe n’a rien d’inéluctable. Une guerre dont la plupart des experts, CIA comprise, prédisaient la fin en quelques mois devrait donc se prolonger."]},{"k":"p","s":["Il est peu probable que Trump change d’avis sur la Russie et l’Ukraine. À ses yeux, la Russie restera un partenaire potentiel, et l’Ukraine un pays qui a reçu l’aide des États-Unis et n’a ",["rendu","https://www.pbs.org/newshour/politics/watch-trump-says-u-s-has-gotten-nothing-from-ukraine-other-than-high-diesel-urging-deal"]," « absolument rien en retour, à part des ennuis »."]},{"k":"p","s":["Mais désormais, politiquement acculé, face à des démocrates aux commandes du Congrès dans un pays qui vient de rendre un verdict sans appel sur sa présidence, il aura sans doute plus de mal à définir son propre programme vis-à-vis de la Russie et de l’Ukraine."]}],"chars":6671},"https://theconversation.com/florida-just-voted-for-lower-property-taxes-and-that-could-mean-cuts-in-government-services-and-new-housing-construction-295716":{"r":"conversation","at":"2026-11-17T17:32Z","sha":"b88b257a523b2df854c846cdeb809ce0e40ef859cc6268a10267498d6de6030c","read":"https://theconversation.com/florida-just-voted-for-lower-property-taxes-and-that-could-mean-cuts-in-government-services-and-new-housing-construction-295716","bytes":187432,"x":"fulltext v1","title":"Florida just voted for lower property taxes – and that could mean cuts in government services and new housing construction","by":[{"n":"Abigail Hall","r":"Professor of Economics, University of Tampa"},{"n":"Aaron D. Wood","r":"Associate Professor of Economics, University of Tampa"}],"pub":"2026-11-04T22:48:26Z","mod":"","blocks":[{"k":"p","s":["Many Florida homeowners cheered on Nov. 3, 2026, when more than 60% of voters ",["approved a constitutional amendment","https://baynews9.com/fl/tampa/news/2026/11/04/florida-voters-approve-amendment--providing-property-tax-relief-for-homeowners"]," to significantly reduce property taxes."]},{"k":"p","s":[["Under the measure, Amendment 3","https://ballotpedia.org/Florida_Amendment_3,_Homestead_Tax_Exemptions,_Property_Assessments,_and_Spending_Restrictions_Amendment_(2026)"],", a homeowner’s tax break known as a ",["homestead exemption","https://ocpaweb.ocpafl.org/faqcontent/HX_FAQ"]," would go from the current US$51,400 to $150,000 in 2027 and increase again to $250,000 in 2028. By shielding more of a home’s assessed value from taxation, this exemption effectively lowers homeowners’ tax bills. New Florida residents who buy a home ",["would also reportedly be eligible","https://floridaphoenix.com/2026/07/07/another-amendment-3-challenge-filed-by-bipartisan-pair-of-former-legislators/"]," for a property tax break, but on a more phased-in basis."]},{"k":"p","s":["But the measure comes with a hefty price tag. The Florida Legislature’s research arm ",["estimated the measure","https://edr.state.fl.us/Content/about/index.cfm"]," would reduce annual revenue from property taxes by ",["$11.8 billion","https://edr.state.fl.us/Content/conferences/revenueimpact/archives/2026F/_pdf/impact0612.pdf"],". This translates to a ",["30% reduction","https://floridataxwatch.org/2023-how-florida-counties-compare/"]," in revenue for Florida counties and a 13% cut for smaller municipal governments."]},{"k":"p","s":["While homeowners will get some relief, the budget crunch due to the lower tax revenue will affect other Floridians in more adverse ways. ",["As economists","https://scholar.google.com/citations?user=sAMhsxQAAAAJ&hl=en"]," ",["who have been following","https://www.ut.edu/directory/wood-aaron-d"]," the debates over Amendment 3, we argue that local governments will struggle to fund basic services with less money. And we expect more sweeping economic consequences as well – including less affordable residential housing and a broader shift of the tax burden away from relatively wealthier homeowners to those who are less well off."]},{"k":"h","s":["How Amendment 3 would work"]},{"k":"p","s":["Much of the political momentum for Amendment 3 came from a rise in the cost of living and ",["frustration over rising property taxes","https://www.nytimes.com/2026/10/30/realestate/florida-property-tax-vote-midterms.html"],". These now average ",["just over $3,000","https://smartasset.com/taxes/florida-property-tax-calculator#O4NOGqPK5X"]," annually but can run much higher for Floridians with ",["more expensive homes","https://smartasset.com/taxes/florida-property-tax-calculator"],"."]},{"k":"p","s":["In addition to raising the homestead tax exemption, Amendment 3 lowers the cap on annual assessments on rental and commercial properties from ",["a 10% increase","https://ocpaimages.ocpafl.org/api/Content/GetContentDynamicFile?contentFileID=149816"]," to ",["a 5% increase","https://www.flsenate.gov/Session/Bill/2026F/2F/BillText/c1/PDF"],". Since property taxes are based on an asset’s assessed value, this language effectively limits but doesn’t rule out tax hikes for businesses."]},{"k":"p","s":["So landlords, for example, could still see ",["meaningful annual tax increases","https://www.flhouse.gov/Sections/Documents/loaddoc.aspx?BillNumber=1&DocumentType=Analysis&FileName=h0001z.SAC.DOCX&Session=2026F"]," as their properties go up in value – costs that would likely be passed on to renters."]},{"k":"p","s":["Amendment 3 makes clear that school-related property taxes ",["are exempt","https://ballotpedia.org/Florida_Amendment_3,_Homestead_Tax_Exemptions,_Property_Assessments,_and_Spending_Restrictions_Amendment_(2026)"]," from these tax cuts. It also lists ",["some theoretical limits","https://www.flsenate.gov/Session/Bill/2026F/2F/BillText/c1/PDF"]," on how local governments should use tax dollars, as a way to ensure continued funding for essential services such as public safety, infrastructure or obligations for employee retirement benefits."]},{"k":"p","s":["But it also states that funds may be used for “ ",["expenditures approved","https://www.flhouse.gov/Sections/Documents/loaddoc.aspx?BillNumber=1&DocumentType=Analysis&FileName=h0001z.SAC.DOCX&Session=2026F"],"” by local and county governments – ambiguous wording that suggests these stipulations can be breached."]},{"k":"h","s":["Who pays the bill?"]},{"k":"p","s":["Florida property taxes are levied and collected by some 640 local government entities. There’s ",["no state income tax","https://floridarevenue.com/property/Documents/ptoinfographic.pdf"],", so any reductions in property tax revenue directly affect local and county governments."]},{"k":"p","s":["With tax revenue slashed, businesses, landlords and owners of other non-homestead properties like second homes would almost certainly see their taxes go up. This is a typical pattern: ",["When governments","https://edr.state.fl.us/content/presentations/property-tax-study/EDR-Presentation-on-Interim-Findings.pdf"]," ",["cut property taxes","https://taxfoundation.org/research/all/state/property-tax-repeal-replace-revenue/"]," for some groups, ",["taxes shift","https://www.lincolninst.edu/publications/books/erosion-property-tax-base/"]," to other groups."]},{"k":"p","s":["This dynamic is likely to play out with local governments as they try to keep revenue stable: Amendment 3 would force them to ",["hike taxes in other areas","https://edr.state.fl.us/Content/revenues/reports/fiscal-analysis-in-brief/FiscalAnalysisinBrief2025.pdf"]," to make up for the shortfall. This could include increases in state and local sales taxes, an expansion of the list of goods ",["subject to sales taxes","https://floridarevenue.com/forms_library/current/dr46nt.pdf"],", or a hike in “ ",["documentary stamp taxes","https://floridarevenue.com/Forms_library/current/gt800014.pdf"],",” which are required on documents such as deeds, bonds and mortgages."]},{"k":"p","s":["State and local governments could also impose higher fees for specific services, such as ",["solid waste treatment","https://floridadep.gov/sites/default/files/2023%20Florida%20Solid%20Waste%20Disposal%20Fees.pdf"]," and ",["stormwater utilities","https://fsa.memberclicks.net/stormwater-utility-rates-in-florida"],". Another option is to hike ",["permits and inspection fees","https://hcfl.gov/businesses/permits-and-records/permit-fees"],", ",["fuel taxes","https://impactfees.org/florida-impact-fees"]," or other ",["service charges","https://floridalicenseplate.org/vehicle-registration-fees"]," such as vehicle registration fees."]},{"k":"p","s":["Finally, local governments could raise ",["tourism-related taxes","https://floridarevenue.com/taxes/taxesfees/Pages/local_option.aspx"],", such as on food, beverages and hotels. But this recourse wouldn’t help counties with limited tourism, and such revenues fluctuate in any event."]},{"k":"p","s":["In the end, though, essential services would still almost certainly be affected. Funding for police, fire and emergency medical services is ",["primarily the responsibility","https://edr.state.fl.us/Content/local-government/data/revenues-expenditures/stwidefiscal.cfm"]," of local governments, and, for most counties, they make up the ",["largest line item","https://flicg.org/wp-content/uploads/2021/03/revenue-and-expenditure-booklet-2021_WEB-Version.pdf"]," in their annual expenditures. Reducing ",["property taxes","https://edr.state.fl.us/Content/local-government/data/revenues-expenditures/stwidefiscal.cfm"]," would amount to a direct hit, especially in smaller, less-populated counties."]},{"k":"p","s":["And if local governments do raise sales tax rates to the extent they can, lower-income Floridians will bear a disproportionate burden as they spend much more of their income on consumption. They’re also far more likely to rent than own a home, so any increased rents would take a bigger toll."]},{"k":"h","s":["A looming affordable housing crunch?"]},{"k":"p","s":["Less noticed in the debate over Amendment 3 was how it would affect the state’s ",["affordable housing shortage","https://www.jpmorgan.com/insights/real-estate/community-development-banking/floridas-affordable-housing-crisis"],". We argue that the structure of the property tax cut will likely create more incentives for counties and developers to build commercial structures instead of more residential housing."]},{"k":"p","s":["When developers build residential homes, they require a basic level of public services to support residents and the local infrastructure. In fact, property taxes in much of Florida effectively subsidize residential home development: For every dollar that a homeowner pays in property taxes, ",["it costs county governments around $1.20","https://hcfl.gov/government/your-property-tax-investment"]," to provide those services. This gap will only grow when property tax revenues fall."]},{"k":"p","s":["From the standpoint of local and county governments, then, ",["it may make more sense","https://www.oecd.org/en/publications/local-taxation-land-use-regulation-and-land-use_52da7c6a-en.html"]," to focus on commercial or industrial construction as a way to keep tax revenues stable. But ",["with fewer homes built","https://www.hklaw.com/en/insights/publications/2026/09/florida-homestead-exemption-proposal-could-reshape-family-development"]," at the expense of business construction – from manufacturing to data centers – the supply squeeze will only drive up prices and rents for the workers who are needed for those jobs."]},{"k":"p","s":["Now that Amendment 3 is on the books, Florida’s county and local governments will confront major trade-offs. We believe that state officials will come to realize how much of a change has been made – and how quickly their priorities may have to shift."]},{"k":"p","s":["This article has been corrected to note that the current homestead exemption is $51,400 and that new Florida residents who buy a home are eligible for a property tax break on a phased-in basis."]},{"k":"p","s":["Portions of this article appeared in a ",["prior article","https://theconversation.com/floridas-proposed-property-tax-amendment-will-require-trade-offs-and-some-residents-could-end-up-with-higher-costs-287149"]," published on July 30, 2026."]}],"chars":6289},"https://theconversation.com/your-nature-strip-could-be-a-haven-for-native-plants-and-insects-new-research-293929":{"r":"conversation","at":"2026-11-18T01:30Z","sha":"e126bdcc7f336820fb7b123eda0bbdbf81d00b9debd9295d2e863b4aee101f95","read":"https://theconversation.com/your-nature-strip-could-be-a-haven-for-native-plants-and-insects-new-research-293929","bytes":188253,"x":"fulltext v1","title":"Your nature strip could be a haven for native plants and insects: new research","by":[{"n":"Philippa Bell","r":"Urban Ecologist and Research Fellow, Interdisciplinary Conservation Science Research Group, The University of Melbourne"}],"pub":"2026-11-18T00:16:51Z","mod":"","blocks":[{"k":"p","s":["Native plants are springing up across our cities and towns."]},{"k":"p","s":["Whether they are winning popular ",["garden shows","https://melbflowershow.com.au/show-features/landscape-design-show-gardens/"]," or gracing living ",["art galleries","https://nga.gov.au/stories-ideas/flourishing-flora/"],", these colourful and quirky plants have captured our attention."]},{"k":"p","s":["Now that spring has sprung, our native plants are showcasing a dizzying array of colours, shapes and textures. These plants are also uniquely adaptable, able to thrive with little water or maintenance. And they provide much-needed food and habitat for local wildlife."]},{"k":"p","s":["Our ",["new research","https://doi.org/10.1111/1365-2664.70567"]," investigated how native plants could help bridge the gap between our natural and urban environments – starting with the humble nature strip."]},{"k":"h","s":["Not enough natives"]},{"k":"p","s":[["Native plants","https://www.nwf.org/Native-Plant-Habitats/Plant-Native/Why-Native"]," are those that naturally occur in Australia and were here before European settlement."]},{"k":"p","s":["Over millions of years, these plants have evolved alongside our native animals. Some native plants depend entirely on a handful of native animals to complete their lifecycle, and vice versa. For example, native orchids typically rely on one species of wasp for pollination and mimic the ",["look and smell","https://www.australiangeographic.com.au/news/2014/09/deceptive-orchids-luring-wasps-for-pollination/"]," of female wasps to trick males into visiting their flowers."]},{"k":"p","s":["Worryingly, our native plants and animals are ",["under threat","https://biodiversitycouncil.org.au/news/how-do-we-know-australia-is-in-a-biodiversity-crisis-a-summary-of-the-science-1"],". This ",["biodiversity crisis","https://doi.org/10.1111/emr.12594"]," is driven by various factors including climate change, the spread of invasive species and land clearing for agriculture and urbanisation."]},{"k":"p","s":["In general, the world’s cities have not been built to support nature. But that’s not to say nature doesn’t belong in the city. Many cities act ",["as havens","https://doi.org/10.1111/geb.12404"]," for threatened species, providing novel spaces for plants and animals to thrive."]},{"k":"p","s":["Growing ",["native plants","https://doi.org/10.1016/j.biocon.2026.111743"]," as a form of habitat restoration is one way we can support our native animals. Yet, current housing and development trends mean private gardens are increasingly hard to find. While house sizes have increased in the past 20 years, the average block size in Melbourne has ",["decreased by 22%","https://www.abs.gov.au/articles/australians-building-houses-smaller-blocks"],"."]},{"k":"p","s":["That’s where nature-strip gardens come in."]},{"k":"p","s":["Read more: ",["Thousands of our native plants have no public photographs available. Here’s why that matters","https://theconversation.com/thousands-of-our-native-plants-have-no-public-photographs-available-heres-why-that-matters-199100"]]},{"k":"h","s":["Remind me, what are nature strips?"]},{"k":"p","s":[["Nature strips","https://www.monash.vic.gov.au/Residents-Property/Trees-and-Nature-Strips/Nature-Strips/Planting-on-nature-strips-guidelines-and-permit/What-is-a-nature-strip"]," are areas of public land between a private property and the kerb. While owned by the government, nature strips are privately maintained. This means the homeowner or renter is responsible for keeping their nature strip tidy."]},{"k":"p","s":["These strips of land are typically composed of lawn and a street tree. This traditional set-up offers few resources to animals that rely on the nutrients and shelter provided by native plants."]},{"k":"p","s":["Fortunately, ",["most councils","https://www.melbourne.vic.gov.au/street-garden-permits"]," across Greater Melbourne allow residents to turn nature strips into gardens as a way to boost biodiversity. The same is true across Australia, though the specifics can vary between councils."]},{"k":"p","s":["But no research has investigated whether this approach actually works. Until now."]},{"k":"p","s":["Read more: ",["Our land abounds in nature strips – surely we can do more than mow a third of urban green space","https://theconversation.com/our-land-abounds-in-nature-strips-surely-we-can-do-more-than-mow-a-third-of-urban-green-space-124781"]]},{"k":"h","s":["What we did and found"]},{"k":"p","s":["Our ",["new study","https://doi.org/10.1111/1365-2664.70567"]," investigated whether native nature-strip gardens could become habitat for insect pollinators."]},{"k":"p","s":["We planted native gardens in nature strips across the City of Merri-bek in Melbourne’s inner north. We monitored which insects visited the gardens both before and after this transformation."]},{"k":"p","s":["We found seven times more ",["insect pollinators","https://australian.museum/learn/animals/insects/pollination/"]," buzzing around the nature-strip gardens, compared to only-lawn nature strips. There were also double the number of species in the planted nature strips."]},{"k":"p","s":["These results were mainly driven by ",["native bees","https://theconversation.com/are-australias-native-bees-thriving-or-declining-we-dont-know-but-can-find-out-292219"],", which forage for nectar and pollen in flowers of Wahlenbergia, Goodenia ovata and Brachyscome multifida."]},{"k":"p","s":["In Melbourne, nature strips and other kinds of road verges make up more than ",["one third","https://doi.org/10.1016/j.ufug.2019.126423"]," of public green space. They represent a crucial opportunity to revegetate our cities and protect the native species living alongside us."]},{"k":"p","s":["Read more: ",["Are Australia’s native bees thriving or declining? We don’t know but can find out","https://theconversation.com/are-australias-native-bees-thriving-or-declining-we-dont-know-but-can-find-out-292219"]]},{"k":"h","s":["How can I get involved?"]},{"k":"p","s":["If you’re keen to plant a nature-strip garden, start by searching “nature strip guidelines” on your local council website, checking if you need a permit to alter your nature strip. From there, you can contact local nurseries or communities to learn what native plants and animals live in your area. The ",["Gardens for Wildlife","https://gardensforwildlifevictoria.com/affiliates/"]," website is another handy resource."]},{"k":"p","s":["Next comes the actual gardening. Perhaps the hardest part of creating a nature-strip garden is removing the existing lawn. Lawn grasses are designed to be tough. Be ready ",["to solarise","https://trueleafmarket.com/blogs/articles/grass-to-garden-chemical-free-lawn-conversion-using-solarization?srsltid=AfmBOopq9rjF7NvDmhbkhC7ulVdnFYAVGU5LCn0kTIcYNuZVL9IXPGIX"]," – which involves placing a clear plastic tarp over grass to kill weeds – or apply ",["sheet mulch","https://www.abc.net.au/gardening/how-to/sheet-mulching/101512534"]," to prepare a lawn for planting."]},{"k":"p","s":["This process takes time, so be patient. But get this done over summer, and you’ll be planting in autumn. This lets your garden settle in through the cooler, wetter months and come up looking its best by spring."]},{"k":"p","s":["When planting, aim to grow a wide variety of native plants. Having flowering plants of different colours, shapes and sizes allows an array of animals to forage in your nature-strip garden. Resources like the City of Melbourne’s ",["Urban Nature Planting Guide","https://www.melbourne.vic.gov.au/planting-guide"]," can help you choose plants that suit the streetscape environment."]},{"k":"p","s":["While planting one or a few nature-strip gardens is a good start, collective action is key. So once you transform your nature strip, spread the word. It may even help you and your neighbours ",["reconnect with nature","https://doi.org/10.1016/j.jenvp.2019.101323"],", with all the ",["health and wellbeing","https://doi.org/10.1038/s41598-024-56968-5"]," benefits that brings."]},{"k":"p","s":["It’s time to put the nature back into nature strips."]},{"k":"p","s":["Read more: ",["How do we keep gardening in the face of a changing climate?","https://theconversation.com/how-do-we-keep-gardening-in-the-face-of-a-changing-climate-72647"]]}],"chars":5471},"https://theconversation.com/canadas-new-immigration-points-system-rewards-experience-but-not-for-skills-gained-abroad-295648":{"r":"conversation","at":"2026-11-25T21:06Z","sha":"b2f1e4c31df42e1a9bed676d3f2e8007c2fee3e623527008c1032501ab9afd6d","read":"https://theconversation.com/canadas-new-immigration-points-system-rewards-experience-but-not-for-skills-gained-abroad-295648","bytes":185141,"x":"fulltext v1","title":"Canada’s new immigration points system rewards experience, but not for skills gained abroad","by":[{"n":"Sheri Adekola","r":"Sessional Instructor, Migration and Labour Markets, University of Guelph"}],"pub":"2026-11-25T19:33:43Z","mod":"","blocks":[{"k":"p","s":[["New Express Entry points reward Canadian experience in high-wage jobs","https://www.canada.ca/en/immigration-refugees-citizenship/news/2026/10/changes-to-express-entry-for-high-wage-occupations.html"],". For internationally trained professionals facing licensing barriers, that experience can be difficult to obtain."]},{"k":"p","s":["Consider two internationally educated nurses living in Canada. Both have years of clinical experience abroad and want to continue working in nursing."]},{"k":"p","s":["One has obtained Canadian registration and spent the past year as a registered nurse. The other has worked as a personal support worker while navigating licensing requirements."]},{"k":"p","s":["Under changes to Canada’s Express Entry system that recently took effect, their Canadian work histories can produce significantly different immigration scores. The difference is not necessarily their expertise, but their access to Canadian professional employment."]},{"k":"p","s":["This raises an important question: Is Canada selecting immigrants for the skills they possess or the opportunities they have already accessed?"]},{"k":"p","s":["Read more: ",["My grandfather kept his rejected degree for 50 years. Decades later, Canada still deskills immigrants","https://theconversation.com/my-grandfather-kept-his-rejected-degree-for-50-years-decades-later-canada-still-deskills-immigrants-286824"]]},{"k":"h","s":["What changed"]},{"k":"p","s":["Express Entry ranks candidates for Canada’s main economic immigration programs using factors such as education, language proficiency and work experience. Candidates could already earn up to 80 points for Canadian work experience."]},{"k":"p","s":["Now, at least one year of Canadian experience in a high-wage occupation adds 20, 40 or 70 points, depending on the occupation’s median wage. A qualifying job offer can earn 50 to 100 points. ",["Candidates receive whichever is higher, not both","https://www.canada.ca/en/immigration-refugees-citizenship/news/2026/10/changes-to-express-entry-for-high-wage-occupations.html"],"."]},{"k":"p","s":["The classification reflects an occupation’s typical earnings, not an individual’s salary. Eligible experience must generally be gained in Canada within the past 10 years in qualifying occupations."]},{"k":"p","s":["The federal government says the changes emphasize ",["“factors linked to stronger economic outcomes.”","https://www.canada.ca/en/immigration-refugees-citizenship/news/2026/10/canada-refocusing-express-entry-on-top-talent-that-drives-economic-growth.html"],". That rationale has merit. Immigration, Refugees and Citizenship Canada’s (IRCC) ",["research on Express Entry labour-market outcomes","https://www.canada.ca/en/immigration-refugees-citizenship/corporate/reports-statistics/research/express-entry-labour-market-outcomes-economic-immigrants.html"]," found that immigrants with more Canadian work experience generally had higher employment incomes and wages after becoming permanent residents."]},{"k":"p","s":["But Canadian experience is not equally accessible to everyone."]},{"k":"h","s":["What the points actually measure"]},{"k":"p","s":["In regulated professions, licensing bodies determine whether qualifications earned abroad meet Canadian standards. Assessments, examinations and supervised practice can delay professional entry, leaving qualified professionals working below their training level."]},{"k":"p","s":["Under the new system, that interim employment matters. Registered nurses qualify for an additional 40 points after a year of Canadian employment, while personal support workers are ",["not on the high-wage list","https://www.canada.ca/en/immigration-refugees-citizenship/services/immigrate-canada/express-entry/check-score/high-wage.html"],"."]},{"k":"p","s":["Both occupations can count toward existing Canadian work-experience points, but only registered nurses receive the additional high-wage bonus. Experience gained abroad, however extensive, receives no equivalent high-wage bonus beyond ",["existing skill-transferability points","https://www.canada.ca/en/immigration-refugees-citizenship/services/immigrate-canada/express-entry/changes.html"],"."]},{"k":"p","s":["The system therefore distinguishes workers partly by the occupations they can enter, reflecting both labour-market differences and potential barriers to professional recognition."]},{"k":"h","s":["What my research shows"]},{"k":"p","s":["My research on Black internationally educated health professionals illustrates these barriers. In a mixed-methods study involving 132 participants in Canada and Nigeria, 65 per cent of respondents ",["reported barriers to credential recognition","https://doi.org/10.1177/08404704261468561"],"."]},{"k":"p","s":["In a related study of Nigerian health workers in Canada, 76 per cent participated in activities to ",["acquire new professional credentials","https://doi.org/10.1007/s44155-026-00444-0"],"."]},{"k":"p","s":["For many, obtaining Canadian professional recognition requires time and resources. During that transition, they may be unable to accumulate experience in the occupations the new points reward."]},{"k":"p","s":["A policy that rewards Canadian occupational experience also inherits the conditions that determine who gets that experience."]},{"k":"h","s":["Health-care recruitment difficulties"]},{"k":"p","s":["Canada has prioritized health-care workers through dedicated Express Entry categories and, since December 2025, a category for doctors. Yet the doctors’ category requires Canadian work experience."]},{"k":"p","s":["This creates tensions between attracting internationally trained professionals and rewarding those who have already gained Canadian professional experience."]},{"k":"p","s":["The reforms don’t eliminate recognition of foreign experience. However, they give an additional advantage to candidates whose qualifications have already translated into qualifying Canadian employment."]},{"k":"p","s":["The professionals Canada seeks to attract may not always be those who benefit most from its new selection criteria."]},{"k":"p","s":["For a country facing health-care staffing pressures, the distinction matters: recruiting internationally trained professionals does not guarantee that their skills will be used in the occupations where they are needed."]},{"k":"p","s":["Read more: ",["How the nursing shortage is affecting the health-care system, patients and nurses themselves","https://theconversation.com/how-the-nursing-shortage-is-affecting-the-health-care-system-patients-and-nurses-themselves-228259"]]},{"k":"h","s":["What Canada should measure"]},{"k":"p","s":["The changes may improve earnings among selected immigrants. But higher earnings alone doesn’t necessarily mean the system has identified the most capable professionals. It could also indicate that the system increasingly selects people who have already overcome barriers to higher-paying Canadian employment."]},{"k":"p","s":["IRCC should report invitation outcomes by occupation, particularly for regulated professions, and examine how internationally acquired qualifications influence selection outcomes."]},{"k":"p","s":["Closer co-ordination between federal immigration selection and provincial professional licensing could also identify where qualified candidates encounter barriers."]},{"k":"p","s":["Canada’s immigration system should recognize more than who has already succeeded in its labour market. It should also recognize the expertise internationally trained professionals bring with them."]}],"chars":5698}};
